L3_1.m_Talk_KOREA = "뭐야, 여기가 네 차고라도 되는 줄 알아?"
L3_1.m_fTalkTime = 0.03
L3_1.m_Talk_JPN = "何よ？　ここはあなたの車庫なんかじゃないわよ？"
L3_1.m_Talk_ENG = "Huh? You think you own this place?"
L3_1.m_Talk_TWN = "怎麼搞的？你以為這裡是你的車庫嗎？"
L3_1.m_Talk_THA = "ฮะ? คุณคิดว่าคุณเป็นเจ้าของสถานที่นี้เหรอ?"
L3_1.m_Talk_VTN = "Hử? Cậu tưởng cậu sở hữu nơi này à?"
L3_1.m_Talk_SCN = "什么啊，你当这里是你的车库吗？"
L3_1.m_Talk_DEU = "Was zum?! Denkst du etwa, dass dieses Penthouse dir gehört?"
L3_1.m_Talk_FRA = "Hein ? Tu te crois chez mamie ou quoi ?"
