L6_1.m_Face = "UNIT_DESPAIR"
L6_1.m_CharStrID = "GOLD_CHARADE_NULL_NULL"
L6_1.m_Pos = "L"
L6_1.m_Talk_KOREA = "방 좀 빌려줬다고 엉망으로 만들어 놨네."
L6_1.m_fTalkTime = 0.03
L6_1.m_Talk_JPN = "ちょっと部屋を貸してあげたら、めちゃくちゃにしちゃって。"
L6_1.m_Talk_ENG = "I let you stay, and you've made it into this mess."
L6_1.m_Talk_TWN = "我把房間借給你，結果你把這裡搞得一團糟。"
L6_1.m_Talk_THA = "ฉันปล่อยให้คุณอยู่ และคุณก็ทำให้มันยุ่งวุ่นวายนี้"
L6_1.m_Talk_VTN = "Tôi để cậu ở lại, thế mà cậu đã biến nó thành mớ hỗn loạn này."
L6_1.m_Talk_SCN = "我好心把房间借给你住，但你竟然弄得乱七八糟的。"
L6_1.m_Talk_DEU = "Ich habe dich hier netterweise wohnen lassen und zum Dank hast du die Wohnung in einen einzigen Saustall verwandelt."
L6_1.m_Talk_FRA = "Je t'autorise à rester ici, et voilà comment tu me remercies ?! En mettant la pagaille ?"
L7_1 = {}
L7_1.m_CutScenKey_Talk = "CHARADE2_ACT2_STAGE2_START@7#Talk"
L7_1.m_CutScenProcessKey = 7
L7_1.m_CutScenID = 5700207
L7_1.m_CutScenStrID = "CHARADE2_ACT2_STAGE2_START"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_Face = "UNIT_SERIOUS"
L7_1.m_CharStrID = "GOLD_CHARADE_NULL_NULL"
L7_1.m_Pos = "L"
L7_1.m_Crash = 15
L7_1.m_Talk_KOREA = "으, 기름 냄새. 샤레이드 최고의 파티 플레이스가 꼴이 이게 뭐람."
L7_1.m_fTalkTime = 0.03
L7_1.m_Talk_JPN = "うう、オイル臭い。シャレード一のパーティープレイスがなんて様なのかしら。"
L7_1.m_Talk_ENG = "Ugh, the smell of grease. You ruined Charade's best party place."
L7_1.m_Talk_TWN = "唔，好臭的汽油味，怎麼把查雷德最屌的派對地點搞成這樣啦！"
L7_1.m_Talk_THA = "อืม ได้กลิ่นน้ำมัน คุณทำลายสถานที่ปาร์ตี้ที่ดีที่สุดของชาเรด"
L7_1.m_Talk_VTN = "Ugh, mùi dầu mỡ. Cậu đã phá hỏng nơi tiệc tùng tuyệt nhất của Charade rồi."
L7_1.m_Talk_SCN = "呃，一股油味。查雷德最棒的派对地点成什么样子了。"
L7_1.m_Talk_DEU = "Urgh, dieser ölige Geruch. Du hast Charades besten Partyort komplett ruiniert."
L7_1.m_Talk_FRA = "Argh, cette odeur de cambouis. Tu as ruiné le meilleur endroit de Charade pour faire la fête !"
L8_1 = {}
L8_1.m_CutScenKey_Talk = "CHARADE2_ACT2_STAGE2_START@8#Talk"
L8_1.m_CutScenProcessKey = 8
L8_1.m_CutScenID = 5700207
L8_1.m_CutScenStrID = "CHARADE2_ACT2_STAGE2_START"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_CharStrID = "WYLER_CHARADE_NPC_NULL"
L8_1.m_Pos = "R"
L8_1.m_Talk_KOREA = "다음 경기에 내보낼 테니 만전을 기하라고 한 건 당신이었을 텐데."
L8_1.m_fTalkTime = 0.03
L8_1.m_Talk_JPN = "次の試合に出すから、十分に準備しておけと言ったのはお前だったはずだが。"
L8_1.m_Talk_ENG = "You're the one who told me to get ready to be sent out on the next match."
L8_1.m_Talk_TWN = "你不是說下一場比賽要派我上場，要我做好萬全準備嗎？"
L8_1.m_Talk_THA = "คุณเป็นคนบอกให้ฉันเตรียมพร้อมส่งออกในนัดหน้า"
L8_1.m_Talk_VTN = "Chính cô là người đã bảo tôi hãy chuẩn bị sẵn sàng để được tung vào sân trong trận đấu tiếp theo."
L8_1.m_Talk_SCN = "是你说会让我参加下一个比赛，所以要我做到万无一失。"
L8_1.m_Talk_DEU = "Du warst doch diejenige, die gesagt hat, ich solle mich darauf vorbereiten, für das nächste Spiel entsandt zu werden."
L8_1.m_Talk_FRA = "C'est toi qui m'as dit de me tenir prêt pour être envoyé lors du prochain match."
L9_1 = {}
L9_1.m_CutScenKey_Talk = "CHARADE2_ACT2_STAGE2_START@9#Talk"
L9_1.m_CutScenProcessKey = 9
L9_1.m_CutScenID = 5700207
L9_1.m_CutScenStrID = "CHARADE2_ACT2_STAGE2_START"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_Face = "UNIT_IDLE"
L9_1.m_CharStrID = "GOLD_CHARADE_NULL_NULL"
L9_1.m_Pos = "L"
L9_1.m_Talk_KOREA = "만전을 기한다고 준비하는 게 겨우 민수용 아라크네야?"
L9_1.m_fTalkTime = 0.03
L9_1.m_Talk_JPN = "十分準備するっていうのが、たかが民需用アラクネなの？"
L9_1.m_Talk_ENG = "And all you've prepared so far is a civilian version of Arachne?"
L9_1.m_Talk_TWN = "你所謂的萬全準備就是民用阿拉克涅？"
L9_1.m_Talk_THA = "และสิ่งที่คุณเตรียมไว้จนถึงตอนนี้ก็คืออรัคเน่ ซึ่งเป็นเครื่องจักรพลเรือนใช่ไหม?"
L9_1.m_Talk_VTN = "Và tất cả những gì cậu đã chuẩn bị đến giờ là một phiên bản dân sự Arachne?"
L9_1.m_Talk_SCN = "所以你为了万无一失准备的就是区区民用阿拉克涅？"
L9_1.m_Talk_DEU = "Und alles, was du bisher vorbereitet hast, ist eine zivile Version von Arachne?"
L9_1.m_Talk_FRA = "Et tout ce que tu as fais jusqu'à présent, c'est une version civile d'Arachne ?"
L10_1 = {}
L10_1.m_CutScenKey_Talk = "CHARADE2_ACT2_STAGE2_START@10#Talk"
L10_1.m_CutScenProcessKey = 10
L10_1.m_CutScenID = 5700207
L10_1.m_CutScenStrID = "CHARADE2_ACT2_STAGE2_START"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L10_1.m_Face = "UNIT_SERIOUS"
L10_1.m_CharStrID = "GOLD_CHARADE_NULL_NULL"
L10_1.m_Pos = "L"
L10_1.m_Crash = 10
L10_1.m_Talk_KOREA = "나는 네 총 다루는 솜씨를 높이 사서 불러 온 거야. 그깟 손 재주가 아니라."
L10_1.m_fTalkTime = 0.03
L10_1.m_Talk_JPN = "私は、あなたの銃さばきを高く評価して呼んだのよ。そういう器用さじゃなくてね。"
L10_1.m_Talk_ENG = "I got you out for your gunslinging skills. Not your tinkering skills."
L10_1.m_Talk_TWN = "我找你來是因為你的槍法過人，不是找你來當黑手的。"
L10_1.m_Talk_THA = "ฉันพาคุณออกมาเพราะทักษะการยิงปืนของคุณ ไม่ใช่ทักษะการซ่อมแซมของคุณ"
L10_1.m_Talk_VTN = "Tôi đã giúp cậu ra vì kỹ năng bắn súng của cậu. Chứ không phải kỹ năng mày mò đó."
L10_1.m_Talk_SCN = "我让你来，是因为看重你的枪法，而不是你那点修补匠的手艺。"
L10_1.m_Talk_DEU = "Ich habe dich hierher gebracht, weil ich deine Fähigkeiten im Umgang mit Waffen bewundere. Nicht wegen deines Basteltalents."
L10_1.m_Talk_FRA = "Si je t'ai sorti d'affaire, c'est pour tes compétences de tir. Pas pour tes compétences de bricolage."
L11_1 = {}
L11_1.m_CutScenKey_Talk = "CHARADE2_ACT2_STAGE2_START@11#Talk"
L11_1.m_CutScenProcessKey = 11
L11_1.m_CutScenID = 5700207
L11_1.m_CutScenStrID = "CHARADE2_ACT2_STAGE2_START"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L11_1.m_CharStrID = "WYLER_CHARADE_NPC_NULL"
L11_1.m_Pos = "R"
L11_1.m_Talk_KOREA = "기계에 대해서는 문외한이로군."
L11_1.m_fTalkTime = 0.03
L11_1.m_Talk_JPN = "機械については素人なんだな。"
L11_1.m_Talk_ENG = "It's obvious that you know nothing about machines."
L11_1.m_Talk_TWN = "看來在機械方面你是門外漢呢。"
L11_1.m_Talk_THA = "เห็นได้ชัดว่าคุณไม่รู้อะไรเลยเกี่ยวกับเครื่องจักร"
L11_1.m_Talk_VTN = "Rõ ràng là cô không biết gì về máy móc."
L11_1.m_Talk_SCN = "关于机器，你还真是个外行啊。"
L11_1.m_Talk_DEU = "Du hast doch überhaupt keine Ahnung von Maschinen."
L11_1.m_Talk_FRA = "De toute évidence, tu n'y connais rien en machines."
L12_1 = {}
L12_1.m_CutScenKey_Talk = "CHARADE2_ACT2_STAGE2_START@12#Talk"
L12_1.m_CutScenProcessKey = 12
L12_1.m_CutScenID = 5700207
L12_1.m_CutScenStrID = "CHARADE2_ACT2_STAGE2_START"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "WYLER_CHARADE_NPC_NULL"
L12_1.m_Pos = "R"
L12_1.m_Talk_KOREA = "확실히 이것들은 평범한 민수용 아라크네다. 하지만 이걸 쓴다면…… 이야기가 다르지."
L12_1.m_fTalkTime = 0.03
L12_1.m_Talk_JPN = "確かにこれらは普通の民需用アラクネだ。だが、これを付ければ……話は違う。"
L12_1.m_Talk_ENG = "Yes, these are just ordinary civilian Arachnes. But with this... they become something else."
L12_1.m_Talk_TWN = "這些確實是普通的民用阿拉克涅，但只要用上這個……就完全是另一個層次。"
L12_1.m_Talk_THA = "ใช่แล้ว พวกนี้เป็นเพียงพลเรือนอรัคเน่ ธรรมดาๆ เท่านั้น แต่ด้วยสิ่งนี้... พวกมันจึงกลายเป็นอย่างอื่นไป"
L12_1.m_Talk_VTN = "Đúng, đây chỉ là Arachne dân sự bình thường. Nhưng với thứ này... chúng trở thành một thứ khác."
L12_1.m_Talk_SCN = "这些确实是普通的民用阿拉克涅。但如果加上这个……那就不一样了。"
L12_1.m_Talk_DEU = "Ja, dies sind nur gewöhnliche zivile Arachnes. Aber hiermit ... werden sie zu etwas Anderem."
L12_1.m_Talk_FRA = "Oui, ce ne sont que des Arachnes civiles ordinaires. Mais avec ça... c'est une toute autre histoire."
L13_1 = {}
L13_1.m_CutScenKey_Talk = "CHARADE2_ACT2_STAGE2_START@13#Talk"
L13_1.m_CutScenProcessKey = 13
L13_1.m_CutScenID = 5700207
L13_1.m_CutScenStrID = "CHARADE2_ACT2_STAGE2_START"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_Face = "UNIT_SURPRISE"
L13_1.m_StartFXSoundName = "FX_COMBAT_ALL_MOVEMENT_02"
L13_1.m_CharStrID = "GOLD_CHARADE_NULL_NULL"
L13_1.m_Pos = "L"
L13_1.m_Crash = 10
L13_1.m_Talk_KOREA = "벌레잖아? 곤충 채집 좋아할 나이란 말은 처음 듣는데?"
L13_1.m_fTalkTime = 0.03
L13_1.m_Talk_JPN = "虫？　昆虫採集が好きな歳だったなんて、聞いてないわよ。"
L13_1.m_Talk_ENG = "A bug? I didn't know you were at that age of catching bugs."
L13_1.m_Talk_TWN = "這不是蟲嗎？原來你還在喜歡抓昆蟲的年紀嗎？"
L13_1.m_Talk_THA = "หนอนหรอ? ฉันไม่รู้ว่าคุณอยู่ในวัยที่สามารถจับแมลงได้"
L13_1.m_Talk_VTN = "Một con bọ? Tôi không biết cậu vẫn ở độ tuổi bắt bọ đó."
L13_1.m_Talk_SCN = "那不是虫子吗？到了你这个年龄还喜欢收集昆虫？"
L13_1.m_Talk_DEU = "Ein Käfer? Ich wusste nicht, dass man in deinem Alter noch Insekten sammelt."
L13_1.m_Talk_FRA = "Un insecte ? Je pensais que tu avais passé l'âge d'attraper des insectes."
L14_1 = {}
L14_1.m_CutScenKey_Talk = "CHARADE2_ACT2_STAGE2_START@14#Talk"
L14_1.m_CutScenProcessKey = 14
