L14_1.m_Talk_KOREA = "너무 비아냥거리진 마, 챔피언."
L14_1.m_fTalkTime = 0.03
L14_1.m_Talk_JPN = "あまり皮肉るな、チャンピオン。"
L14_1.m_Talk_ENG = "Don't be so sarcastic, champion."
L14_1.m_Talk_TWN = "冠軍，說話不需要那麼酸。"
L14_1.m_Talk_THA = "อย่าประชดมากนะแชมป์"
L14_1.m_Talk_VTN = "Đừng mỉa mai thế, nhà vô địch."
L14_1.m_Talk_SCN = "别太嘲讽我，冠军。"
L14_1.m_Talk_DEU = "Sei nicht so sarkastisch, Champion."
L14_1.m_Talk_FRA = "Ne sois pas si désobligeante, championne."
