L16_1.m_CharScaleTime = 0.01
L16_1.m_Talk_KOREA = "이건 예전 동업자에게 받은 기생충이다."
L16_1.m_fTalkTime = 0.03
L16_1.m_Talk_JPN = "これは昔、同業者からもらった寄生虫だ。"
L16_1.m_Talk_ENG = "This is a parasite I got from my former partner."
L16_1.m_Talk_TWN = "這個寄生蟲是我以前的同事給我的。"
L16_1.m_Talk_THA = "นี่คือสิ่งที่ที่ผมได้รับจากสหายเก่าของผม"
L16_1.m_Talk_VTN = "Đây là một loại ký sinh trùng tôi có được từ bạn đời cũ của mình."
L16_1.m_Talk_SCN = "这是我从以前的同行那里得到的寄生虫。"
L16_1.m_Talk_DEU = "Dies ist ein Parasit, den ich von meiner ehemaligen Partnerin bekommen habe."
L16_1.m_Talk_FRA = "C'est un parasite que j'ai reçu de la part de mon ancien partenaire."
