L17_1.m_CharScale = L18_1
L17_1.m_CharScaleTime = 0.01
L17_1.m_Talk_KOREA = "기갑병기의 인공지능을 강제로 오버클럭시켜서 카탈로그보다 몇 배나 뛰어난 성능을 내게 하지."
L17_1.m_fTalkTime = 0.03
L17_1.m_Talk_JPN = "機甲兵器の人工知能を強制オーバークロックさせ、カタログより何倍も優れた性能を発揮させる。"
L17_1.m_Talk_ENG = "It forcefully overclocks the armored unit's AI, causing it to perform several times better than stated in the catalog."
L17_1.m_Talk_TWN = "牠可以強制使機甲兵器的人工智慧超頻，發揮出比原設定高出好幾倍的性能。"
L17_1.m_Talk_THA = "มันบังคับโอเวอร์คล็อก AI ของหน่วยหุ้มเกราะ ทำให้มันทำงานได้ดีกว่าที่ระบุไว้ในคู่มือหลายเท่า"
L17_1.m_Talk_VTN = "Nó ép xung AI của đơn vị thiết giáp một cách mạnh mẽ, khiến nó hoạt động tốt hơn nhiều lần so với mô tả trong danh mục."
L17_1.m_Talk_SCN = "让机甲兵器的人工智能强行超频，使其发挥超出几倍的性能。"
L17_1.m_Talk_DEU = "Er übertaktet die KI der gepanzerten Einheit so stark, dass sie um ein Vielfaches besser ist als im Katalog angegeben."
L17_1.m_Talk_FRA = "Il permet d'overclocker de force l'IA des unités blindées et ses performances sont plusieurs fois supérieures à celles cataloguées."
