L18_1.m_CharScale = L19_1
L18_1.m_CharScaleTime = 0.01
L18_1.m_Talk_KOREA = "프레임은 오래 못 버티겠지만, 망가지기 전까진 군용 이상의 위력을 보여줄 거다."
L18_1.m_fTalkTime = 0.03
L18_1.m_Talk_JPN = "フレームは長持ちしないが、壊れるまでは軍用以上の威力を見せてくれるはずだ。"
L18_1.m_Talk_ENG = "Though its frame won't hold for long, it will output more power than its military counterpart until it breaks down."
L18_1.m_Talk_TWN = "雖然機體本身無法撐太久，但在損壞前會展現出超出軍用以上的威力。"
L18_1.m_Talk_THA = "แม้ว่าโครงของมันจะอยู่ได้ไม่นาน แต่มันก็จะปล่อยพลังออกมามากกว่ากองกำลังทหารจนกว่ามันจะพังทลายลง"
L18_1.m_Talk_VTN = "Mặc dù khung của nó không tồn tại được lâu nhưng nó sẽ tạo ra nhiều năng lượng hơn so với đối tác quân sự cho đến khi bị hỏng."
L18_1.m_Talk_SCN = "躯壳虽然支撑不了多久，但在被破坏掉之前能发挥出军用以上的威力。"
L18_1.m_Talk_DEU = "Obwohl sein Rahmen nicht lange hält, wird er mehr Energie abgeben als sein militärisches Gegenstück, bis er letztendlich zusammenbricht."
L18_1.m_Talk_FRA = "Bien que son armature ne tienne pas longtemps, il produit plus de puissance que son homologue militaire jusqu'à ce qu'il se décompose."
