L21_1.m_Pos = "L"
L21_1.m_Talk_KOREA = "그걸, 주최 측을 속이고 값싼 포인트로 쓰겠다는 거구나?"
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "それを、主催側を騙して安いポイントで使うってわけね。"
L21_1.m_Talk_ENG = "So you're spending fewer points by deceiving the organizers, eh?"
L21_1.m_Talk_TWN = "原來你是想瞞過主辦方的眼睛，以便宜的點數使用它？"
L21_1.m_Talk_THA = "หลอกผู้จัดงานใช้แต้มน้อยลงใช่ไหม?"
L21_1.m_Talk_VTN = "Vậy là cậu lừa dối ban tổ chức để tốn ít điểm hơn phải không?"
L21_1.m_Talk_SCN = "你是说，欺骗主办方，作为廉价的点数使用？"
L21_1.m_Talk_DEU = "Du verwendest also weniger Punkte, indem du die Organisatoren mit diesem Ding täuscht?"
L21_1.m_Talk_FRA = "Alors tu dépenses moins de points en trompant les organisateurs, c'est ça ?"
