L30_1 = "UNIT_LAUGH"
L29_1.m_Face = L30_1
L29_1.m_CharStrID = "GOLD_CHARADE_NULL_NULL"
L29_1.m_Pos = "C"
L29_1.m_Crash = 30
L30_1 = "흐음. 좋아. 그게 네 방식이라면, 존중해 줄게."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "ふーん。いいわ。それがあなたのやり方なら、尊重してあげる。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Hmm. Okay. If that's your style, I'll respect it."
L29_1.m_Talk_ENG = L30_1
L30_1 = "嗯哼，好吧，我尊重你的做法。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "อืม ตกลง ถ้านั่นเป็นเทดนิดของคุณ ฉันจะรับมันไว้"
L29_1.m_Talk_THA = L30_1
L30_1 = "Hm. Được rồi. Nếu đó là phong cách của cậu, tôi sẽ tôn trọng nó."
L29_1.m_Talk_VTN = L30_1
L30_1 = "唔，好吧。如果那是你的方式，我尊重你。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Hmm. Okay. Wenn das deine Art und Weise ist, zu kämpfen, werde ich es respektieren."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Humm. D'accord. Si c'est ta manière de faire, je la respecterai."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "CHARADE2_ACT2_STAGE2_START@30#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L30_1.m_CutScenProcessKey = 30
L30_1.m_CutScenID = 5700207
L30_1.m_CutScenStrID = "CHARADE2_ACT2_STAGE2_START"
