L30_1.m_Face = "UNIT_IDLE"
L30_1.m_CharStrID = "GOLD_CHARADE_NULL_NULL"
L30_1.m_Pos = "C"
L31_1 = "자기 방식으로 최선을 다해서 싸우는 게 건틀렛 정신이니까."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "自分のやり方で頑張って戦うのがガントレット精神だもの。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "It's the Gauntlet spirit to fight in your own unique way."
L30_1.m_Talk_ENG = L31_1
L31_1 = "用自己的方法盡全力戰鬥，這就是聖鎧精神。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "มันคือจิตวิญญาณของกอนต์เล็ตที่จะต่อสู้ในแบบเฉพาะตัวของคุณเอง"
L30_1.m_Talk_THA = L31_1
L31_1 = "Đó là tinh thần Gauntlet để chiến đấu theo cách riêng của cậu."
L30_1.m_Talk_VTN = L31_1
L31_1 = "因为用自己的方式尽全力战斗，就是圣铠的精神。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Schließlich besteht der Sinn der Fehde darin, so gut man kann, auf seine eigene Art und Weise zu kämpfen."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Combattre à sa manière, c'est ça l'esprit de la Compétition."
L30_1.m_Talk_FRA = L31_1
