L35_1 = "그보다 조금 있으면 경기 시작인데, 전력 분석이라도 해야 하지 않겠어?"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "それよりもうすぐ試合が始まるけど、戦力の分析でもしておいた方がいいんじゃないかしら？"
L34_1.m_Talk_JPN = L35_1
L35_1 = "By the way, a match is going to start soon. Don't you need to analyze their strategy or something?"
L34_1.m_Talk_ENG = L35_1
