L49_1 = "밋치미치는 저런 어려운 얘기는 하나도 모르겠어~"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "ミッチーミッチーは、あんな難しいこと全っ然わからないんだよね～"
L48_1.m_Talk_JPN = L49_1
L49_1 = "It's so hard to understand for Mitchie-Mitchie!"
L48_1.m_Talk_ENG = L49_1
L49_1 = "米琪個人覺得內容好難，完全聽不懂呢～"
L48_1.m_Talk_TWN = L49_1
L49_1 = "มันยากมากที่จะเข้าใจสำหรับมิทชี่-มิทชี่!"
L48_1.m_Talk_THA = L49_1
L49_1 = "Thật khó hiểu đối với Mitchie-Mitchie!"
L48_1.m_Talk_VTN = L49_1
L49_1 = "米琪米琪一点都听不懂那种很难的东西呢~"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Für mich, Mitchie-Mitchie, war dieses strategische Gelaber so schwer zu verstehen!"
L48_1.m_Talk_DEU = L49_1
L49_1 = "Moi je n'ai absolument rien pipé à ce qui a été dit !"
