L49_1[L50_1] = L51_1
L50_1 = "하지만 여러분이 좋아하는 편파 중계는 맡겨달라구?"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "でも、みんなが大好きな不公平中継なら任せて！"
L49_1.m_Talk_JPN = L50_1
L50_1 = "But I can handle casting your favorite, biased stream!"
L49_1.m_Talk_ENG = L50_1
L50_1 = "不過各位最愛的不中立轉播就交給我吧！"
L49_1.m_Talk_TWN = L50_1
L50_1 = "แต่ฉันสามารถจัดการแคสต์สตรีมที่คุณชื่นชอบและลำเอียงได้!"
L49_1.m_Talk_THA = L50_1
L50_1 = "Nhưng tôi có thể xử lý việc truyền phát đội bạn thiên vị và yêu thích!"
L49_1.m_Talk_VTN = L50_1
L50_1 = "不过大家喜欢的不公正解说就交给我吧？"
L49_1.m_Talk_SCN = L50_1
