L3_1[2] = L5_1
L1_1[L2_1] = L3_1
L2_1 = "먼저, 방어팀부터 소개해볼까?"
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "まずは、防御チームから紹介してみようかな？"
L1_1.m_Talk_JPN = L2_1
L2_1 = "First, let me introduce the defending team!"
L1_1.m_Talk_ENG = L2_1
L2_1 = "先介紹我們的防守方吧？"
L1_1.m_Talk_TWN = L2_1
L2_1 = "ก่อนอื่นขอแนะนำทีมป้องกันก่อน!"
L1_1.m_Talk_THA = L2_1
L2_1 = "Đầu tiên xin giới thiệu đội phòng thủ!"
L1_1.m_Talk_VTN = L2_1
L2_1 = "先来介绍一下防御队！"
