L3_1 = "m_CutScenKey_SubTitle"
L4_1 = "CHARADE2_ACT2_STAGE2_START@52#SubTitle"
L2_1[L3_1] = L4_1
L3_1 = 52
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 5700207
L2_1.m_CutScenStrID = "CHARADE2_ACT2_STAGE2_START"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L3_1 = "m_fTitleTalkTime"
L2_1[L3_1] = 0
L3_1 = "m_SubTitle_KOREA"
L4_1 = "<color=#ffd34c>■■■</color> 밋치미치! 오늘도 진짜 예뻐! 건풍선 잔뜩 쏴줄게ㅋㅋ\n<color=#ffd34c>■■</color> 카나리아아아아 스쿼드으으으!!!\n<color=#ffd34c>■■</color> 얘네 진짜 독종임 ㅋㅋ\n<color=#ffd34c>■■</color> 어떻게 첫 경기부터 함선을 들이받냐고 ㅋㅋ"
L2_1[L3_1] = L4_1
L3_1 = "m_fSubTitleTalkTime"
L2_1[L3_1] = 0
L3_1 = "m_SubTitle_JPN"
L4_1 = "<color=#ffd34c>■■■</color> ミッチーミッチー！　今日もマジかわいい！　投げ銭たくさん投げちゃうねｗｗ\n<color=#ffd34c>■■</color> カナリアアアァァ～スクワッドォォォ！！！\n<color=#ffd34c>■■</color> こいつらマジ鬼ｗｗ\n<color=#ffd34c>■■</color> 初試合から艦船に突進するなんてｗｗ"
L2_1[L3_1] = L4_1
L3_1 = "m_SubTitle_ENG"
L4_1 = "<color=#ffd34c>■■■</color> Mitchie-Mitchie! You look so cute today! I'll be donating Gauntbits all the way! LOL!\n<color=#ffd34c>■■</color> CANARY SQUAAAAD!!!\n<color=#ffd34c>■■</color> They're really something, aren't they? HAHA!\n<color=#ffd34c>■■</color> Who would've thought about crashing their ship in the first round? LOL!"
L2_1[L3_1] = L4_1
L3_1 = "m_SubTitle_TWN"
L4_1 = "<color=#ffd34c>■■■</color> 米琪！今天也超美的！我要狂按愛心，呵呵\n<color=#ffd34c>■■</color> 金～～絲～～雀～～～！！！\n<color=#ffd34c>■■</color> 她們真的不好對付欸，呵呵\n<color=#ffd34c>■■</color>哪有一開始就撞爛艦船的啦，呵呵"
L2_1[L3_1] = L4_1
L3_1 = "m_SubTitle_THA"
L4_1 = "<color=#ffd34c>■■■</color> มิทชี่-มิทชี่! วันนี้คุณดูน่ารักมาก! ฉันจะบริจาคกอนต์บิตตลอดไป! ฮ่าๆ!\n<color=#ffd34c>■■</color>หน่วยแคนารี!!!\n<color=#ffd34c>■■</color> เป็นอะไรบางอย่างจริงๆ ใช่ไหม? ฮ่าฮ่า!\n<color=#ffd34c>■■</color> ใครจะคิดจะทำลายยานในรอบแรกบ้าง? ฮ่าๆ!"
L2_1[L3_1] = L4_1
L3_1 = "m_SubTitle_VTN"
L4_1 = "<color=#ffd34c>■■■</color> Mitchie-Mitchie! Hôm nay trông cô thật dễ thương! Tôi sẽ quyên góp Gauntbits bằng mọi cách! LOL!\n<color=#ffd34c>■■</color> TIỂU ĐỘI CANARYYYYY!!!\n<color=#ffd34c>■■</color> Họ thực sự là có tí khả năng, phải không? HAHA!\n<color=#ffd34c>■■</color> Ai lại nghĩ đến việc đâm tàu ở trận đầu tiên chứ? CƯỜI!"
L2_1[L3_1] = L4_1
L3_1 = "m_SubTitle_SCN"
L4_1 = "<color=#ffd34c>■■■</color>米琪米琪！你今天真美！我会给你很多打赏的，嘿嘿\n<color=#ffd34c>■■</color>金丝雀小队啊啊啊啊！！！\n<color=#ffd34c>■■</color>他们真的不一般，呵呵\n<color=#ffd34c>■■</color>怎么会在第一场比赛直接撞向舰船啊，噗哈哈"
L2_1[L3_1] = L4_1
L3_1 = "m_SubTitle_DEU"
