L5_1 = "예선부터 질풍가도를 달리고 있다! 리그 첫 경기에 첫 키스를 박아버린 파란의 주인공─!"
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "予選から疾風怒濤！　リーグ初試合で初キスをぶつけちゃった波瀾の主人公─！"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Blazing through everything from the start of the qualifiers! The stars of adversity who went straight in for the first kiss on their first match!"
L4_1.m_Talk_ENG = L5_1
L5_1 = "從預賽開始一路過關斬將！在聯賽的第一場比賽就使出艦船衝撞的戲劇性主角─！"
L4_1.m_Talk_TWN = L5_1
L5_1 = "ทะลุทะลวงทุกสิ่งตั้งแต่เริ่มรอบคัดเลือก! ดาราแห่งความทุกข์ยากที่ตรงเข้ามาเพื่อปะทะแรกในนัดแรก!"
L4_1.m_Talk_THA = L5_1
L5_1 = "Vượt qua mọi thứ ngay từ đầu vòng loại! Những ngôi sao của nghịch cảnh đã lao thẳng tới nụ hôn đầu tiên trong trận đầu tiên của họ!"
L4_1.m_Talk_VTN = L5_1
L5_1 = "从预赛就引起了一阵疾风！联赛第一场比赛就献出了初吻的冷门主人公——！"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Sie haben bereits seit der Qualifikationsrunde für viel Aufruhr gesorgt! Die dunkelblauen Helden, die sich gleich bei ihrem ersten Spiel den ersten Kuss gegönnt haben ─!"
L4_1.m_Talk_DEU = L5_1
L5_1 = "Elles ont explosé tous les records depuis le début des qualifications ! Nos chères protagonistes bleues qui ont eu droit à leur Premier baiser lors du premier match de la Compétition..."
