L8_1 = "m_SubTitle_KOREA"
L9_1 = "<color=#ffd34c>■■■■</color> ????????????????\n<color=#ffd34c>■■■</color> 어라???? 진짜네??? \n<color=#ffd34c>■■■</color>얘네 팀 엔트리에 카운터가 늘었는데???\n<color=#ffd34c>■ ■</color> 노엘 말고 새로운 카운터가 있다고??????\n<color=#ffd34c>■■■■</color> 남는 포인트는 근성에 투자하는 카나리아 어디갔어!!"
L7_1[L8_1] = L9_1
L8_1 = "m_fSubTitleTalkTime"
L7_1[L8_1] = 0
L7_1.m_fTalkTime = 0.03
L8_1 = "m_SubTitle_JPN"
L9_1 = "<color=#ffd34c>■■■■</color> ？？？？？？？？？？？？？？？？\n<color=#ffd34c>■■■</color> あれ？？？？　ホントだ？？？\n<color=#ffd34c>■■■</color> こいつらのチームエントリーにカウンターが増えてるぞ？？？\n<color=#ffd34c>■ ■</color> ノエル以外に新しいカウンターがいるってこと？？？？？？\n<color=#ffd34c>■■■■</color> 残りのポイントは根性に投資するカナリアはどこ行った！！"
L7_1[L8_1] = L9_1
L8_1 = "m_SubTitle_ENG"
L9_1 = "<color=#ffd34c>■■■■</color> ????????????????\n<color=#ffd34c>■■■</color> Huh? You're right!!\n<color=#ffd34c>■■■</color> They got more Counters in their roster now???\n<color=#ffd34c>■ ■</color> They have another Counter besides Noelle??????\n<color=#ffd34c>■■■■</color> Where's the Canary that put all their points into grit?!"
L7_1[L8_1] = L9_1
L8_1 = "m_SubTitle_TWN"
L9_1 = "<color=#ffd34c>■■■■</color> ？？？？？？？\n<color=#ffd34c>■■■</color> 真假？？還真的欸？？？\n<color=#ffd34c>■■■</color>她們隊上的制裁者變多咧？？？\n<color=#ffd34c>■ ■</color> 除洛艾兒之外還有其他制裁者？？？\n<color=#ffd34c>■■■■</color> 把多出來的點數都投資在毅力上的金絲雀呢！！"
L7_1[L8_1] = L9_1
L8_1 = "m_SubTitle_THA"
L9_1 = "<color=#ffd34c>■■■■</color> ????????????????\n<color=#ffd34c>■■■</color> หืม? คุณพูดถูก!!\n<color=#ffd34c>■■■</color> พวกเขามีตัวสำรองในบัญชีรายชื่อแล้ว???\n<color=#ffd34c>■ ■</color> พวกเขามีตัวสำรอง นอกจากโนเอลแล้ว??????\n<color=#ffd34c>■■■■</color> นกแคนารี่อยู่ไหนที่เอาคะแนนเต็มไปหมด?!"
L7_1[L8_1] = L9_1
L8_1 = "m_SubTitle_VTN"
L9_1 = "<color=#ffd34c>■■■■</color> ????????????????\n<color=#ffd34c>■■■</color> Hả? Đúng thế!!\n<color=#ffd34c>■■■</color> Bây giờ họ có nhiều Counter hơn trong danh sách???\n<color=#ffd34c>■ ■</color> Họ có một Counter khác ngoài Noelle ??????\n<color=#ffd34c>■■■■</color>Canary đã dồn hết điểm vào sự gan dạ đâu rồi?!"
L7_1[L8_1] = L9_1
L8_1 = "m_SubTitle_SCN"
L9_1 = "<color=#ffd34c>■■■■</color>？？？？？？？\n<color=#ffd34c>■■■</color>咦？？？是真的欸？？？\n<color=#ffd34c>■■■</color>参赛选手名单上多了制裁者啊？？？\n<color=#ffd34c>■ ■</color>除了诺艾尔以外，还有新的制裁者？？？？？\n<color=#ffd34c>■■■■</color>剩下的点数都投在毅力的精神哪儿去了！！"
L7_1[L8_1] = L9_1
L8_1 = "m_SubTitle_DEU"
L9_1 = "<color=#ffd34c>■■■■</color> ????????????????\n<color=#ffd34c>■■■</color> Häh???? Du hast recht?! \n<color=#ffd34c>■■■</color> Sie haben jetzt mehr Counter in ihrer Formation?!\n<color=#ffd34c>■ ■</color> Sie haben außer Noelle noch einen Counter??????\n<color=#ffd34c>■■■■</color> Wo ist der Canary Trupp hin, der seine gesamten Punkte in sein Durchhaltevermögen gesteckt hat?!"
L7_1[L8_1] = L9_1
L8_1 = "m_SubTitle_FRA"
L9_1 = "<color=#ffd34c>■■■■</color> What ????\n<color=#ffd34c>■■■</color> Hein ?? Mais oui c'est vrai !!\n<color=#ffd34c>■■■</color> Il y a un Counter en plus dans leur équipe ?!\n<color=#ffd34c>■ ■</color> Un autre Counter en plus de Noelle ????\n<color=#ffd34c>■■■■</color> Ils sont passés où les Canaris qui mettent tous leurs points sur leur cran ?"
