L24_1.m_Talk_TWN = L25_1
L25_1 = "เฮ้อ ถ้าฉันต่อสู้เคียงข้างเคาน์เตอร์เกรด S ตำแหน่งของฉันใน หน่วยเฟนเรียร์ คือ..."
L24_1.m_Talk_THA = L25_1
L25_1 = "Ngh, nếu tôi chiến đấu bên cạnh một Counter cấp S, thì vị trí của tôi trong Tiểu Đội Fenrir là..."
L24_1.m_Talk_VTN = L25_1
L25_1 = "呃，和S级制裁者并肩作战，那刚成为芬里尔小队队员的我的地位就……"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Oh, wenn ich Seite an Seite mit einem Klasse-S-Counter kämpfe, dann ist mein Platz im Fenrir-Trupp ..."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Euh, si je me bats aux côtés d'un Counter de grade S, alors ma place dans l'Escouade Fenrir est..."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
