L27_1 = "MINA_FENRIR_CHIEF_NULL"
L26_1.m_CharStrID = L27_1
L26_1.m_Pos = "L"
L27_1 = "저 사람, 종종 회사에 출근해서 청소를 해줬거든."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "あの人、よく会社に出勤して掃除してくれてたから。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "He used to come over to our company and clean the place."
L26_1.m_Talk_ENG = L27_1
L27_1 = "他只是常常來幫忙打掃公司而已。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "เขาเคยมาที่บริษัทของเราและทำความสะอาดสถานที่"
L26_1.m_Talk_THA = L27_1
L27_1 = "Cậu ấy từng đến công ty chúng ta và dọn dẹp nơi này."
L26_1.m_Talk_VTN = L27_1
L27_1 = "那个人之前经常来公司上班打扫来着。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Dieser Typ kam manchmal bei unserem Unternehmen vorbei, um die Böden zu schrubben."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Avant ça, il venait dans notre entreprise pour faire le ménage."
L26_1.m_Talk_FRA = L27_1
