L28_1 = "CHARADE2_ACT2_STAGE2_START@77#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 77
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 5700207
L27_1.m_CutScenStrID = "CHARADE2_ACT2_STAGE2_START"
L27_1.m_bWaitClick = true
