L28_1 = "MINA_FENRIR_CHIEF_NULL"
L27_1.m_CharStrID = L28_1
L27_1.m_Pos = "L"
L28_1 = "그게 솜씨가 좋아서 붙은 별명이야."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "掃除の腕があまりにもいいから付いたあだ名。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "He got that nickname because he was good."
L27_1.m_Talk_ENG = L28_1
L28_1 = "因為掃得很乾淨才會那樣叫他。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "เขาได้รับฉายานั้นเพราะเขาเป็นคนดี"
L27_1.m_Talk_THA = L28_1
L28_1 = "Cậu ấy có biệt danh đó vì rất giỏi."
L27_1.m_Talk_VTN = L28_1
L28_1 = "那时候手脚麻利，所以才会起了那样的绰号。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Er war so gut darin, dass er diesen Spitznamen erhalten hat."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Il a obtenu ce surnom parce qu'il était doué."
L27_1.m_Talk_FRA = L28_1
