L29_1 = "……그럼 S급 청소요원?"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "……じゃあ、S級の掃除エージェント？"
L28_1.m_Talk_JPN = L29_1
L29_1 = "...So he's a Grade S cleaning agent?"
L28_1.m_Talk_ENG = L29_1
L29_1 = "……所以是S級清潔特工喔？"
L28_1.m_Talk_TWN = L29_1
L29_1 = "...เขาเป็นภารโรงเกรด S เหรอ?"
L28_1.m_Talk_THA = L29_1
L29_1 = "…Vậy anh ta là người gác cổng cấp S?"
L28_1.m_Talk_VTN = L29_1
L29_1 = "……所以说，是S级清洁要员？"
L28_1.m_Talk_SCN = L29_1
L29_1 = "... Also ist er eine Klasse-S-Reinigungskraft?"
L28_1.m_Talk_DEU = L29_1
