L32_1 = "ROI_PRYDWEN_NULL_NULL"
L31_1.m_CharStrID = L32_1
L31_1.m_Pos = "C"
L32_1 = "난 그냥 내 눈 앞에 거슬리는 걸 치워버릴 뿐이야."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "俺はただ、自分の目の前にある目障りなものを片付けるだけだぞ。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "I just clean whatever mess that is in front of my eyes."
L31_1.m_Talk_ENG = L32_1
L32_1 = "我只會把眼前礙眼的傢伙除掉而已，"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ผมแค่ทำความสะอาดสิ่งสกปรกที่อยู่ตรงหน้าผม"
L31_1.m_Talk_THA = L32_1
L32_1 = "Tôi chỉ dọn dẹp bất cứ thứ gì lộn xộn trước mắt mình."
L31_1.m_Talk_VTN = L32_1
L32_1 = "我只懂除掉我眼前碍眼的东西而已。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Ich beseitige nur das Chaos, das direkt vor meinen Augen ist."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Je vous rappelle que tout ce que je fais, c'est de nettoyer le désordre qui se trouve devant moi."
L31_1.m_Talk_FRA = L32_1
