L32_1.m_CharStrID = L33_1
L32_1.m_Pos = "C"
L33_1 = "건틀렛 전술 같은 건 하나도 모른다고?"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "ガントレットの戦術とかまったく知らないぜ。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "I know nothing about Gauntlet tactics, you know?"
L32_1.m_Talk_ENG = L33_1
L33_1 = "聖鎧戰術什麼的我可是一竅不通喔？"
L32_1.m_Talk_TWN = L33_1
L33_1 = "ผมไม่รู้อะไรเกี่ยวกับกลยุทธ์ของกอนต์เล็ตเลยรู้ไหม?"
L32_1.m_Talk_THA = L33_1
L33_1 = "Tôi không biết gì về chiến thuật của Gauntlet đâu nhé?"
L32_1.m_Talk_VTN = L33_1
L33_1 = "对圣铠战术什么的一无所知啊。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Ich habe überhaupt keine Ahnung, was Fehde-Taktiken betrifft."
