L36_1 = "CHARADE2_ACT2_STAGE2_START@85#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 85
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 5700207
L35_1.m_CutScenStrID = "CHARADE2_ACT2_STAGE2_START"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_Face = "UNIT_SERIOUS"
L35_1.m_StartFXSoundName = "FX_CUTSCEN_NOISE_RUSTLE_02"
L36_1 = "CHOWON_PERSONA_NULL_NULL"
L35_1.m_CharStrID = L36_1
L35_1.m_Pos = "C"
L36_1 = "걱정하지 마세요. 아무리 훈련을 빙자한 모의전이라고 해도 결국에 전장은 전장."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "心配しないでください。いくら訓練にかこつけた模擬戦だとしても、戦場は戦場。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Don't worry. Even if these mock battles are staged for training purposes, a battlefield is still a battlefield."
L35_1.m_Talk_ENG = L36_1
L36_1 = "盡管放心，雖然是以訓練為名的模擬戰，但戰場就是戰場。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ไม่ต้องกังวล แม้ว่าการต่อสู้จำลองเหล่านี้จะมีขึ้นเพื่อจุดประสงค์ในการฝึกฝน สนามรบก็ยังคงเป็นสนามรบ"
L35_1.m_Talk_THA = L36_1
L36_1 = "Đừng lo. Ngay cả khi những trận chiến giả này được tổ chức để huấn luyện thì chiến trường vẫn là chiến trường."
L35_1.m_Talk_VTN = L36_1
L36_1 = "别担心，就算是借着训练名义的模拟战，但战场就是战场。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Keine Sorge. Auch wenn dieser Scheinkampf nur zu Trainingszwecken inszeniert wurde, ist ein Schlachtfeld immer noch ein Schlachtfeld."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Ne vous inquiétez pas. Même si ces simulations sont mises en place à des fins d'entraînement, un champ de bataille reste un champ de bataille."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "CHARADE2_ACT2_STAGE2_START@86#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 86
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 5700207
L36_1.m_CutScenStrID = "CHARADE2_ACT2_STAGE2_START"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_Face = "UNIT_SERIOUS"
L37_1 = "CHOWON_PERSONA_NULL_NULL"
L36_1.m_CharStrID = L37_1
L36_1.m_Pos = "C"
L37_1 = "그리고 전장에서 승리를 거머쥐는 가장 빠른 방법은 사전에 전장을 장악하는 거죠."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "そして戦場で勝利をもぎ取るもっとも早い方法は、事前に戦場を掌握することです。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "And the fastest way to win is to take control of the battlefield in advance."
L36_1.m_Talk_ENG = L37_1
L37_1 = "而且在戰場上，最快奪勝的方法就是事前掌握戰場。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "และวิธีชนะที่เร็วที่สุดคือการควบคุมสนามรบล่วงหน้า"
L36_1.m_Talk_THA = L37_1
L37_1 = "Và cách nhanh nhất để giành chiến thắng là chiếm quyền kiểm soát chiến trường trước."
L36_1.m_Talk_VTN = L37_1
L37_1 = "而且，在战场上获胜的最快方法，就是事前掌控战场。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Und der schnellste Weg zu gewinnen ist, im Voraus die Kontrolle über das Schlachtfeld zu übernehmen."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Et le moyen le plus rapide de gagner est de prendre le contrôle du champ de bataille à l'avance."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
