L39_1.m_CutScenStrID = "CHARADE2_ACT2_STAGE2_START"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L40_1 = "UNIT_LAUGH"
L39_1.m_Face = L40_1
L40_1 = "CHOWON_PERSONA_NULL_NULL"
L39_1.m_CharStrID = L40_1
L39_1.m_Pos = "C"
L39_1.m_Crash = 10
L40_1 = "네, 사장님께서 후보 선수 제안을 주신 뒤에……."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "はい、社長から候補選手を提案された後に……"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Yes, I did. After you suggested a plan for a substitute player…"
L39_1.m_Talk_ENG = L40_1
L40_1 = "沒錯，老闆提出找一個人來替補的建議後……"
L39_1.m_Talk_TWN = L40_1
L40_1 = "ใช่ฉัน หลังจากที่แนะนำให้ฉันลงทะเบียนเป็นผู้เล่นสำรอง..."
L39_1.m_Talk_THA = L40_1
L40_1 = "Vâng. Sau khi ngài đề xuất kế hoạch cho người chơi thay thế…"
L39_1.m_Talk_VTN = L40_1
L40_1 = "是的，在老板提出候补选手提议之后……"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Ja, das habe ich. Nachdem Sie einen Ersatzspieler vorgeschlagen hatten ..."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Oui je l'ai fait. Après que vous ayez suggéré de faire appel à un joueur de substitution..."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "CHARADE2_ACT2_STAGE2_START@90#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 90
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 5700207
L40_1.m_CutScenStrID = "CHARADE2_ACT2_STAGE2_START"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L40_1.m_StartFXSoundName = "FX_COMBAT_ALL_MOVEMENT_02"
L41_1 = "CHOWON_PERSONA_NULL_NULL"
L40_1.m_CharStrID = L41_1
L40_1.m_Pos = "C"
L41_1 = "금융 지구 전 구역에 고화력 부비트랩을 설치해뒀습니다."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "金融地区の全区域に高火力のブービートラップを設置しておきました。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "I went around the entire financial district and planted highly explosive booby traps."
L40_1.m_Talk_ENG = L41_1
L41_1 = "我就在金融區設下威力強大的詭雷。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ฉันเดินไปรอบๆ ย่านการเงินทั้งหมด และวางกับดักระเบิดแรงสูง"
L40_1.m_Talk_THA = L41_1
L41_1 = "Tôi đã đi vòng quanh toàn bộ khu tài chính và đặt bom có độ nổ cực cao."
L40_1.m_Talk_VTN = L41_1
L41_1 = "我在整个金融区布置了高火力爆炸陷阱。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Habe ich im gesamten Finanzviertel hochexplosive Sprengfallen aufgestellt."
L40_1.m_Talk_DEU = L41_1
L41_1 = "J'ai fait le tour du quartier financier et j'ai planté des pièges hautement explosifs."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "CHARADE2_ACT2_STAGE2_START@91#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 91
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 5700207
L41_1.m_CutScenStrID = "CHARADE2_ACT2_STAGE2_START"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L41_1.m_Face = "UNIT_SERIOUS"
L42_1 = "CHOWON_PERSONA_NULL_NULL"
L41_1.m_CharStrID = L42_1
L41_1.m_Pos = "C"
L42_1 = "저희는 경기가 끝날 때까지 대기하다가 부비트랩에 살아남은 생존자들의 뒤를 치면 됩니다."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "私たちは試合が終わるまで待機し、ブービートラップからの生き残りを処理すればいいのです。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "All we have to do is wait out the match and ambush the remaining survivors."
L41_1.m_Talk_ENG = L42_1
L42_1 = "我們只需要在比賽結束前守株待兔，最後再一併處理掉詭雷的倖存者就好。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "สิ่งที่เราต้องทำคือรอการแข่งขันและซุ่มโจมตีผู้รอดชีวิตที่เหลือ"
L41_1.m_Talk_THA = L42_1
L42_1 = "Tất cả những gì chúng ta phải làm là chờ trận đấu kết thúc và phục kích những kẻ sống sót."
L41_1.m_Talk_VTN = L42_1
L42_1 = "等爆炸结束，我们只要突袭存活下来的幸存者就可以了。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Wir müssen nur abwarten, bis das Spiel vorbei ist und dann die verbleibenden Überlebenden überfallen."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Tout ce qu'il nous reste à faire, c'est d'attendre le match et de tendre une embuscade aux survivants."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
