L43_1[L44_1] = L45_1
L44_1 = "당장 가서 전부 수거하고 오게!"
L43_1.m_Talk_KOREA = L44_1
L44_1 = "今すぐ全部回収して来たまえ！"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Go retrieve all of them right now!"
L43_1.m_Talk_ENG = L44_1
L44_1 = "你立刻把那些詭雷都拆掉！"
L43_1.m_Talk_TWN = L44_1
L44_1 = "ไปเอาพวกมันทั้งหมดมาเดี๋ยวนี้!"
L43_1.m_Talk_THA = L44_1
L44_1 = "Đi gỡ hết ngay!"
L43_1.m_Talk_VTN = L44_1
L44_1 = "马上给我全部撤掉！"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Geh sofort los und sammle sie alle wieder ein!"
L43_1.m_Talk_DEU = L44_1
L44_1 = "Je te prie d'aller récupérer tous tes pièges sur le champ !"
L43_1.m_Talk_FRA = L44_1
