L44_1[L45_1] = L46_1
L45_1 = "상대가 사망하면 즉시 실격일세."
L44_1.m_Talk_KOREA = L45_1
L45_1 = "相手が死亡すると、即失格だ。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "We will get disqualified if any of our opponents die."
L44_1.m_Talk_ENG = L45_1
L45_1 = "若是對方有人死亡，我們就會立刻失去資格。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "เราจะถูกตัดสิทธิ์หากมีคู่ต่อสู้คนใดคนหนึ่งตาย"
L44_1.m_Talk_THA = L45_1
L45_1 = "Chúng ta sẽ bị loại nếu bất kỳ đối thủ nào của chúng ta chết."
L44_1.m_Talk_VTN = L45_1
L45_1 = "若对手死亡，那我们就会被立即淘汰。"
