L47_1.m_Face = "UNIT_HATE"
L48_1 = "CHOWON_PERSONA_NULL_NULL"
L47_1.m_CharStrID = L48_1
L47_1.m_Pos = "C"
L47_1.m_Crash = 20
L48_1 = "그럼 상대의 가족들을 인질로 삼고 협박할 수밖에 없겠네요."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "それでは、相手の家族を人質にして脅すしかありませんね。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Then we have no choice but to take their families hostage and threaten them."
L47_1.m_Talk_ENG = L48_1
L48_1 = "那就只剩下綁架對方家人來當人質這一條路囉。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ถ้าอย่างนั้น เราก็ไม่มีทางเลือกนอกจากจับครอบครัวของพวกเขาเป็นตัวประกันและข่มขู่พวกเขา"
L47_1.m_Talk_THA = L48_1
L48_1 = "Thế thì chúng ta chỉ còn cách bắt gia đình họ làm con tin và đe dọa họ."
L47_1.m_Talk_VTN = L48_1
L48_1 = "那就只剩抓对手的家人当人质以作威胁这一条路了。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Dann haben wir wohl keine andere Wahl, als ihre Familien als Geiseln zu nehmen und sie damit zu erpressen."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Dans ce cas, nous n'avons pas d'autre choix que de prendre leurs familles en otage et de les menacer."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "CHARADE2_ACT2_STAGE2_START@98#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 98
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 5700207
L48_1.m_CutScenStrID = "CHARADE2_ACT2_STAGE2_START"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L48_1.m_Face = "UNIT_SERIOUS"
L49_1 = "CHOWON_PERSONA_NULL_NULL"
L48_1.m_CharStrID = L49_1
L48_1.m_Pos = "C"
L49_1 = "저는 탈락처리로 부탁드리겠습니다. 경기 시작까지 얼마 남지 않았으니 서둘러야겠어요."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "私は失格処理でお願いいたします。試合開始まであと少しですので、急がないと。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Tell the organizers that I'm out. I must hurry, as we don't have much time until the match starts."
L48_1.m_Talk_ENG = L49_1
L49_1 = "那就淘汰我吧，距離比賽開始剩沒多少時間，我要加快動作。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "บอกผู้จัดงานว่าฉันออกไปแล้ว ฉันต้องรีบแล้วเพราะเรามีเวลาไม่มากก่อนที่การแข่งขันจะเริ่มขึ้น"
L48_1.m_Talk_THA = L49_1
L49_1 = "Nói với ban tổ chức là tôi out. Tôi phải nhanh lên vì chúng ta không còn nhiều thời gian cho đến khi trận đấu bắt đầu."
L48_1.m_Talk_VTN = L49_1
L49_1 = "请告诉组委会我临时退出。离比赛开始没剩多少时间了，得抓紧才行。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Sagen Sie den Organisatoren, dass ich aus dem Team ausscheide. Ich muss mich beeilen, da wir nicht mehr viel Zeit haben, bis das Spiel beginnt."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Dites aux organisateurs que j'abandonne. Je dois me dépêcher, car nous n'avons pas beaucoup de temps avant le début du match."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
