L50_1.m_fTalkTime = 0.03
L51_1 = "いや、どうかやめてくれ。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "No, please don't do that."
L50_1.m_Talk_ENG = L51_1
L51_1 = "不，拜託你什麼都別做。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ไม่ โปรดอย่าทำอย่างนั้น"
