L4_1 = "FELICETTE_CANARY_NULL_NULL"
L3_1.m_CharStrID = L4_1
L3_1.m_Pos = "C"
L4_1 = "저한테 할말 있으세요, 코치?"
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "私にお話でもあるんですか？　コーチ。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Is there something you wanted to say to us, Coach?"
L3_1.m_Talk_ENG = L4_1
L4_1 = "教練？你有話要對我說嗎？"
L3_1.m_Talk_TWN = L4_1
L4_1 = "มีอะไรอยากบอกเรามั้ยโค้ช?"
L3_1.m_Talk_THA = L4_1
L4_1 = "Ngài có điều gì muốn nói với chúng tôi không, Huấn Luyện Viên?"
L3_1.m_Talk_VTN = L4_1
L4_1 = "你有话要对我说吗，教练？"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Gibt es etwas, das Sie mir sagen wollen, Trainer?"
L3_1.m_Talk_DEU = L4_1
L4_1 = "Y a-t-il quelque chose que vous vouliez nous dire, coach ?"
