L6_1 = "CHARADE2_ACT2_STAGE2_START@105#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 105
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 5700207
L5_1.m_CutScenStrID = "CHARADE2_ACT2_STAGE2_START"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L6_1 = "USER_ADMIN_NULL_NULL"
L5_1.m_CharStrID = L6_1
L6_1 = "왠지 기운이 없어 보여서 말이야."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "何だか元気がないようだったからな。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "You seem to be down in the dumps for some reason."
L5_1.m_Talk_ENG = L6_1
L6_1 = "你看起來有點無精打采的。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ดูเหมือนคุณจะตกอยู่ในกองขยะด้วยเหตุผลบางอย่าง"
L5_1.m_Talk_THA = L6_1
L6_1 = "Có vẻ như nhóc đang thất vọng vì lý do nào đó."
L5_1.m_Talk_VTN = L6_1
L6_1 = "你看起来好像无精打采的啊，菲利塞特。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Du siehst irgendwie niedergeschlagen aus."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Tu ne sembles pas dans ton assiette, pour une raison que j'ignore."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "CHARADE2_ACT2_STAGE2_START@106#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 106
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 5700207
L6_1.m_CutScenStrID = "CHARADE2_ACT2_STAGE2_START"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L7_1 = "USER_ADMIN_NULL_NULL"
L6_1.m_CharStrID = L7_1
L7_1 = "자네가 라이카 양 일로 힘든 건 이해하지만, 이번 경기는 자네 역할이 무척 중요해."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "君がライカ君のことで辛いのはわかっているが、今度の試合は君の役割がとても重要だ。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "I understand you're worried about Laika. But your role in this match is vital."
L6_1.m_Talk_ENG = L7_1
L7_1 = "我明白萊卡的事你也不好受，但這次的比賽你的角色至關重要。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "ผมเข้าใจว่าคุณกังวลเกี่ยวกับไลกา แต่บทบาทของคุณในการแข่งขันครั้งนี้มีความสำคัญ"
L6_1.m_Talk_THA = L7_1
L7_1 = "Tôi hiểu nhóc đang lo cho Laika. Nhưng vai trò của nhóc trong trận đấu này rất quan trọng."
L6_1.m_Talk_VTN = L7_1
L7_1 = "我知道莱卡的事让你很痛苦，但这次的比赛中你有非常重要的作用。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Ich verstehe ja, dass du dir Sorgen um Leica machst. Aber du übernimmst in diesem Spiel eine entscheidende Rolle."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Je comprends que tu t'inquiètes pour Leica. Mais ton rôle dans ce match est crucial."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "CHARADE2_ACT2_STAGE2_START@107#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 107
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 5700207
L7_1.m_CutScenStrID = "CHARADE2_ACT2_STAGE2_START"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L8_1 = "USER_ADMIN_NULL_NULL"
L7_1.m_CharStrID = L8_1
L8_1 = "로이 군과 초원 양이 각각의 분야에서는 나무랄 데 없지만……."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "ロイ君とナオ君は、各々の分野では申し分ないのだが……"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Roy and Chowon are both experts in their own field, but..."
L7_1.m_Talk_ENG = L8_1
L8_1 = "雖然羅伊和初源在各自的領域都是無可挑剔的，但……"
L7_1.m_Talk_TWN = L8_1
L8_1 = "รอยและโชวอนต่างเป็นผู้เชี่ยวชาญในสาขาของตนเอง แต่..."
L7_1.m_Talk_THA = L8_1
L8_1 = "Roy và Chowon đều là chuyên gia trong lĩnh vực riêng của họ, nhưng..."
L7_1.m_Talk_VTN = L8_1
L8_1 = "虽然罗伊和桃沢梨绘在各自的领域是无可挑剔的……"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Roy und Chowon mögen zwar beide Experten auf ihren jeweiligen Gebieten sein, aber ..."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Roy et Chowon sont tous deux des experts dans leur propre domaine, mais..."
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
