L9_1 = "m_ActionStrKey"
L10_1 = "MARK3"
L8_1[L9_1] = L10_1
L9_1 = "건틀렛에서는 자네의 전술적 판단이 더 위야."
L8_1.m_Talk_KOREA = L9_1
L9_1 = "ガントレットでは君の戦術的な判断の方が上をいく。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "In the Gauntlet, your tactical judgment is far superior."
L8_1.m_Talk_ENG = L9_1
L9_1 = "在聖鎧中更需要你對於戰術面的判斷。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "ในกอนต์เล็ตการตัดสินใจทางยุทธวิธีของคุณนั้นเหนือกว่ามาก"
L8_1.m_Talk_THA = L9_1
L9_1 = "Trong Gauntlet, khả năng phán đoán chiến thuật của cô vượt trội hơn nhiều."
L8_1.m_Talk_VTN = L9_1
L9_1 = "但在圣铠之中，你的战术性判断比他们更高一筹。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "In Fehden bist du ihnen mit deinem taktischen Urteilsvermögen weit überlegen."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Lors de la Compétition, ton jugement tactique est bien supérieur."
L8_1.m_Talk_FRA = L9_1
