L10_1 = "결국 자네의 리더로서의 자질에 승리가 좌우될걸세."
L9_1.m_Talk_KOREA = L10_1
L10_1 = "結局、君のリーダーとしての素質に勝敗がかかっている。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Your leadership will determine the outcome of the match."
