L10_1 = "最後能夠左右勝負的關鍵，就在於你身為隊長的領導能力。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ความเป็นผู้นำของคุณจะเป็นตัวกำหนดผลลัพธ์ของการแข่งขัน"
L9_1.m_Talk_THA = L10_1
L10_1 = "Sự lãnh đạo của cô sẽ quyết định kết quả của trận đấu."
L9_1.m_Talk_VTN = L10_1
L10_1 = "但最终的胜利将取决于你作为队长的资质。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Deine Führung wird den Ausgang des Spiels bestimmen."
L9_1.m_Talk_DEU = L10_1
