L13_1 = "그렇지만, 라이카 없이 저 혼자 이길 수 있을까요?"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "でも、ライカもいないのに私が一人で勝てるんでしょうか？"
L12_1.m_Talk_JPN = L13_1
L13_1 = "But will I be able to win without Laika?"
L12_1.m_Talk_ENG = L13_1
