L29_1 = "Mọi người đã xem chưa? TASKFORCE đã chiến đấu với V.T.A.M. cầm kiếm trong Counterside!"
L28_1.m_Talk_VTN = L29_1
L29_1 = "就是那个啊！在异界和拿着冷兵器的侵蚀体作战的视频！"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Das müsst ihr gesehen haben! Die TASKFORCEs haben in Counterside gegen schwertschwingende C.°O.s gekämpft!"
L28_1.m_Talk_DEU = L29_1
L29_1 = "Non mais sérieusement ? Les TASKFORCEs y ont combattu des O.C. avec des épées dans le Contremonde !"
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "CHARADE2_ACT2_STAGE2_START@129#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 129
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 5700207
L29_1.m_CutScenStrID = "CHARADE2_ACT2_STAGE2_START"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L30_1 = "MITCH_NPC_NULL_NULL"
L29_1.m_CharStrID = L30_1
L30_1 = "이 밋치미치도 진짜 숨죽이면서 봤다니까!"
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "このミッチーミッチーも、本当に固唾を呑んで見守ったんだから！"
L29_1.m_Talk_JPN = L30_1
L30_1 = "I was on the edge of my seat watching it!"
L29_1.m_Talk_ENG = L30_1
L30_1 = "米琪我也是看得膽戰心驚的呢！"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ฉันกำลังดูมันอยู่ขอบที่นั่ง!"
L29_1.m_Talk_THA = L30_1
L30_1 = "Tôi suýt trượt khỏi ghế vì mải xem nó!"
L29_1.m_Talk_VTN = L30_1
L30_1 = "我米琪米琪也是屏住呼吸看完的啊！"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Es war so spannend, dass mir der Atem wegblieb!"
L29_1.m_Talk_DEU = L30_1
L30_1 = "J'ai failli tomber de mon fauteuil quand j'ai vu ça !"
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "CHARADE2_ACT2_STAGE2_START@130#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 130
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 5700207
L30_1.m_CutScenStrID = "CHARADE2_ACT2_STAGE2_START"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L31_1 = "MITCH_NPC_NULL_NULL"
L30_1.m_CharStrID = L31_1
L31_1 = "그런데 대박 사건!! 다들 그거 알고 있었어?"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "でも、大事件！！　みんな、これ知ってた？"
L30_1.m_Talk_JPN = L31_1
L31_1 = "But lo and behold!! Did you guys know this?"
L30_1.m_Talk_ENG = L31_1
L31_1 = "不過還有更驚人的！大家知道嗎？"
L30_1.m_Talk_TWN = L31_1
L31_1 = "แต่เดี๋ยวก่อน!! พวกคุณทราบเรื่องนี้หรือไม่?"
L30_1.m_Talk_THA = L31_1
L31_1 = "Nhưng kìa!! Các bạn đã biết điều này chưa?"
L30_1.m_Talk_VTN = L31_1
L31_1 = "但是，有个惊人的消息！！你们都听说了吗？"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Aber es ist etwas Unglaubliches passiert!! Wusstest ihr das schon?"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Mais le plus surprenant dans tout ça..."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "CHARADE2_ACT2_STAGE2_START@131#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 131
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 5700207
L31_1.m_CutScenStrID = "CHARADE2_ACT2_STAGE2_START"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L32_1 = "MITCH_NPC_NULL_NULL"
L31_1.m_CharStrID = L32_1
L32_1 = "관리국의 정식 라이선스를 발급받은 태스크포스 중에는……."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "管理局の正式ライセンスを持っているタスクフォースの中には……"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Among the TASKFORCEs that have received their official license from the Administration..."
L31_1.m_Talk_ENG = L32_1
L32_1 = "管理局有發給正式執照的特遣勢力中……"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ในบรรดาทาสก์ฟอร์สที่ได้รับใบอนุญาตอย่างเป็นทางการจากฝ่ายบริหาร..."
L31_1.m_Talk_THA = L32_1
L32_1 = "Trong số các TASKFORCE đã nhận được giấy phép chính thức từ Cục Quản Lý..."
L31_1.m_Talk_VTN = L32_1
L32_1 = "得到管理局正式执照的特遣势力中……"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Unter den TASKFORCEs, die ihre offizielle Lizenz von der Administration erhalten haben ..."
L31_1.m_Talk_DEU = L32_1
L32_1 = "C'est que parmi les TASKFORCEs qui ont reçu leur licence officielle de l'Administration..."
L31_1.m_Talk_FRA = L32_1
