L33_1 = "MITCH_NPC_NULL_NULL"
L32_1.m_CharStrID = L33_1
L33_1 = "그 기사 침식체들을 흉내 내고 다니는 녀석들이 있었다는 거?"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "あの騎士の侵食体をマネてる奴らがいたってこと！"
L32_1.m_Talk_JPN = L33_1
L33_1 = "There were those who were mimicking the C.O. knights!"
L32_1.m_Talk_ENG = L33_1
L33_1 = "有人在模仿那些騎士侵蝕體欸？"
L32_1.m_Talk_TWN = L33_1
L33_1 = "มีคนที่เลียนแบบอัศวินวัตถุคอร์รัปต์!"
L32_1.m_Talk_THA = L33_1
L33_1 = "Có những người đang bắt chước các hiệp sĩ V.T.A.M.!"
L32_1.m_Talk_VTN = L33_1
L33_1 = "有模仿那些骑士侵蚀体的家伙们！"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Gab es ein paar Typen, die die Ritter-C.°O.s imitiert haben!"
L32_1.m_Talk_DEU = L33_1
L33_1 = "Il y en avait qui imitaient ces O.C. chevaliers !"
L32_1.m_Talk_FRA = L33_1
