L34_1 = "MITCH_NPC_NULL_NULL"
L33_1.m_CharStrID = L34_1
L34_1 = "으으, 밋치 왠지 소름 돋았어!"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "うう、ミッチ―、何だか鳥肌立っちゃった！"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Wow! Mitchie just got goosebumps!"
L33_1.m_Talk_ENG = L34_1
L34_1 = "天啊，米琪光想就覺得起雞皮疙瘩！"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ว้าว! มิทชี่ถึงกับขนลุก!"
L33_1.m_Talk_THA = L34_1
L34_1 = "Ồ! Mitchie vừa nổi da gà!"
L33_1.m_Talk_VTN = L34_1
L34_1 = "呃呃，米琪都起鸡皮疙瘩了！"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Wow! Ich habe gerade total Gänsehaut bekommen!"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Ohh... Rien que d'y repenser, ça me donne la chair de poule !"
