L36_1.m_CharStrID = L37_1
L36_1.m_Pos = "C"
L37_1 = "아무튼 심야 괴담 방송이 되기 전에 사담은 이쯤 할까나?"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "とにかく、深夜怪談番組になる前に、私語はここまでにしようかな？"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Anyway, let's move on before this stream turns into a late-night horror story stream!"
L36_1.m_Talk_ENG = L37_1
L37_1 = "我怕再說下去會變成深夜怪談，還是點到為止就好。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ยังไงก็มาดูกันก่อนที่สตรีมนี้จะกลายเป็นสตรีมเรื่องสยองขวัญรอบดึก!"
L36_1.m_Talk_THA = L37_1
L37_1 = "Dù sao thì chúng ta hãy tiếp tục trước khi việc này biến thành stream truyện kinh dị đêm khuya nhé!"
L36_1.m_Talk_VTN = L37_1
L37_1 = "总之，在没有成为深夜怪谈直播之前，闲聊就到此为止吧。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Wie auch immer, lasst uns weitermachen, bevor dieser Stream zu einem nächtlichen Horrorgeschichten-Stream wird!"
L36_1.m_Talk_DEU = L37_1
