L40_1 = "오늘의 방어팀! 인류를 위협하는 침식체 기사단─!"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "今日の防御チーム！　人類を脅かす侵食体騎士団─！"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Our defending team for today! The C.O. knights threatening humanity–!"
L39_1.m_Talk_ENG = L40_1
L40_1 = "今天的防守方！威脅人類的侵蝕體騎士團─！"
L39_1.m_Talk_TWN = L40_1
L40_1 = "กองหลังของเราวันนี้! อัศวินวัตถุคอร์รัปต์ คุกคามมนุษยชาติ–!"
L39_1.m_Talk_THA = L40_1
L40_1 = "Đội phòng thủ của chúng ta ngày hôm nay! Các hiệp sĩ V.T.A.M. đang đe dọa nhân loại-!"
L39_1.m_Talk_VTN = L40_1
L40_1 = "今天的防御队！威胁人类的侵蚀体骑士团——！"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Unser heutiges verteidigendes Team! Der C. O.-Ritterorden, der die Menschheit bedroht!"
L39_1.m_Talk_DEU = L40_1
L40_1 = "Notre équipe défensive d'aujourd'hui est... Les Chevaliers O.C. menaçant l'humanité !"
L39_1.m_Talk_FRA = L40_1
