L41_1 = "m_SubTitle_KOREA"
L42_1 = "<color=#ffd34c>■■■■</color> 침식체 기사단이래ㅋㅋ 방송 컨셉 돌았냐구 ㅋㅋ\n<color=#ffd34c>■■</color> 진지하게 맞지 않음? 왜 하필 중세 기사 컨셉인 건데?\n<color=#ffd34c>■ ■</color> 근데 침식체는 괴물 같은 거 아니야?\n<color=#ffd34c>■■</color> 고심도에는 인간이랑 똑같이 생긴 침식체도 있다고 함.\n<color=#ffd34c>■■</color> 그래서 델타 세븐이 헬프 때린 거고 ㅋㅋㅋㅋㅋ\n<color=#ffd34c>■■■</color> 카나리아! 또 함선으로 들이받아서 침식체들 다 죽여버리자!\n<color=#ffd34c>■■■■</color> 이터니움 달달하겠네 ㅋㅋ"
L40_1[L41_1] = L42_1
L41_1 = "m_fSubTitleTalkTime"
L40_1[L41_1] = 0
L41_1 = "m_SubTitle_JPN"
L42_1 = "<color=#ffd34c>■■■■</color> 侵食体騎士団ｗｗコンセプトやばｗｗ\n<color=#ffd34c>■■</color> マジそうじゃん？　なんでよりによって中世時代の騎士コンセプトなんだよ\n<color=#ffd34c>■ ■</color> でも侵食体って、バケモンみたいなものじゃない？\n<color=#ffd34c>■■</color> 高深度には人間そっくりの侵食体もいるんだってさ。\n<color=#ffd34c>■■</color> だからデルタセブンが支援要請したんだしｗｗｗｗｗ\n<color=#ffd34c>■■■</color> カナリア！　また艦船で突進して侵食体を全部殺しちゃおう！\n<color=#ffd34c>■■■■</color> エタニウム儲け、あざーっすｗｗ"
L40_1[L41_1] = L42_1
L41_1 = "m_SubTitle_ENG"
L42_1 = "<color=#ffd34c>■■■■</color> C.O. knights! LOL! That's insane!\n<color=#ffd34c>■■</color> But seriously, why are they so fixated with medieval knights anyway?\n<color=#ffd34c>■ ■</color> Aren't C.O.s supposed to look like monsters or something?\n<color=#ffd34c>■■</color> I heard that there are C.O.s that look exactly like humans in the hyperdepths.\n<color=#ffd34c>■■</color> Is that why Delta Seven called for help? LOL!\n<color=#ffd34c>■■</color> Let's go, Canary! Kill those C.O.s by ramming them with your ship again!\n<color=#ffd34c>■■■■</color> Sounds like that's a lot of Eternium, no? LOL!"
L40_1[L41_1] = L42_1
L41_1 = "m_SubTitle_TWN"
L42_1 = "<color=#ffd34c>■■■■</color> 她說侵蝕體騎士團欸，哈哈哈，這節目瘋啦？呵呵呵\n<color=#ffd34c>■■</color> 錯得離譜？為什麼偏偏要選中世紀騎士風格？\n<color=#ffd34c>■ ■</color> 可是侵蝕體不就是怪物嗎？\n<color=#ffd34c>■■</color>聽說在高深度裡也有長得像人類的侵蝕體。\n<color=#ffd34c>■■</color> 還有第七三角洲的助攻，呵呵呵\n<color=#ffd34c>■■■</color> 金絲雀！再來一次，用艦船撞爛侵蝕體！\n<color=#ffd34c>■■■■</color> 永恆之金很可觀喔，呵呵"
L40_1[L41_1] = L42_1
L41_1 = "m_SubTitle_THA"
L42_1 = "<color=#ffd34c>■■■■</color> วัตถุคอร์รัปต์อัศวิน! ฮ่าๆ! บ้าไปแล้ว!\n<color=#ffd34c>■■</color> แต่จริงๆ แล้ว ทำไมพวกเขาถึงยึดติดกับอัศวินยุคกลางขนาดนั้นล่ะ?\n<color=#ffd34c>■ ■</color>วัตถุคอร์รัปต์ไม่ควรจะทำอย่างนั้นเหรอ? ดูเหมือนสัตว์ประหลาดหรืออะไรสักอย่าง?\n<color=#ffd34c>■■</color> ฉันได้ยินมาว่ามีวัตถุคอร์รัปต์ที่ดูเหมือนมนุษย์ทุกประการในระดับความลึกมาก\n<color=#ffd34c>■■</color> คือ แล้วทำไมเดลต้าเซเว่นถึงขอความช่วยเหลือล่ะ? ฮ่าๆ!\n<color=#ffd34c>■■</color> ไปกันเถอะ แคนารี่! ฆ่าวัตถุคอร์รัปต์พวกนั้นด้วยการพุ่งชนพวกมันด้วยยานของคุณอีกครั้ง!\n<color=#ffd34c>■■■■</color> ฟังดูเหมือนเป็น Eternium เยอะใช่ไหมล่ะ? ฮ่าๆ!"
L40_1[L41_1] = L42_1
L41_1 = "m_SubTitle_VTN"
L42_1 = "<color=#ffd34c>■■■■</color> Hiệp sĩ V.T.A.M.! LOL! Thật điên rồ!\n<color=#ffd34c>■■</color> Nhưng nghiêm túc mà nói, tại sao chúng lại gắn bó với các hiệp sĩ thời trung cổ đến vậy?\n<color=#ffd34c>■ ■</color> V.T.A.M. không phải trông giống quái vật hay sao?\n<color=#ffd34c>■■</color> Tôi nghe nói có những V.T.A.M. trông giống hệt con người ở tầng siêu sâu.\n<color=#ffd34c>■■</color> Đó là lý do tại sao Delta Seven kêu gọi giúp đỡ sao? LOL!\n<color=#ffd34c>■■</color> Tiến lên Canary! Hãy tiêu diệt lũ V.T.A.M. đó, dùng tàu đâm chúng lần nữa đi!\n<color=#ffd34c>■■■■</color> Có vẻ như thế là rất nhiều Vàng Vĩnh Cửu phải không? LOL!"
L40_1[L41_1] = L42_1
L41_1 = "m_SubTitle_SCN"
L42_1 = "<color=#ffd34c>■■■■</color>侵蚀体骑士团，噗哈哈，你这直播风格也太疯狂了吧，哈哈哈\n<color=#ffd34c>■■</color>她说得没错啊？为什么偏偏是中世纪骑士风格？\n<color=#ffd34c>■ ■</color>但侵蚀体不就是怪物吗？\n<color=#ffd34c>■■</color>听说高深度里有和人类长得一模一样的侵蚀体。\n<color=#ffd34c>■■</color>所以德尔塔部队才会求助啊，哈哈哈\n<color=#ffd34c>■■■</color>金丝雀！这次也用舰船撞死所有侵蚀体吧！\n<color=#ffd34c>■■■■</color>听起来有很多能晶的样子，哈哈"
L40_1[L41_1] = L42_1
L41_1 = "m_SubTitle_DEU"
L42_1 = "<color=#ffd34c>■■■■</color> Ritter-C.°O.s?! LOL! Was soll das denn sein?\n<color=#ffd34c>■■</color> Warum haben sie sich denn ein mittelalterliches Ritterkonzept ausgesucht?\n<color=#ffd34c>■ ■</color> Sind C.°O.s nicht eigentlich Monster und keine Ritter?\n<color=#ffd34c>■■</color> Ich habe gehört, dass es in den Hypertiefen C.°O.s gibt, die wie Menschen aussehen.\n<color=#ffd34c>■■</color> Ist das der Grund, warum Delta Seven um Hilfe gerufen hat? LOL!\n<color=#ffd34c>■■■</color> Na los, Canary Trupp! Rammt euer Schiff in diese C.°O.s und macht sie damit platt!\n<color=#ffd34c>■■■■</color> Das Eternium muss ja echt süß schmecken. Haha!"
L40_1[L41_1] = L42_1
L41_1 = "m_SubTitle_FRA"
L42_1 = "<color=#ffd34c>■■■■</color> Les Chevaliers O.C. ? lol Trop chelou ce concept\n<color=#ffd34c>■■</color> Sérieusement ? C'est quoi ce concept de chevaliers médiévaux là ?\n<color=#ffd34c>■ ■</color> Mais les O.C. c'est pas des genre de monstres ?\n<color=#ffd34c>■■</color> Askip, y'a des O.C. qui ressemblent à des humains dans les hyperprofondeurs\n<color=#ffd34c>■■</color> C'est pour ça que les Delta Seven ont demandé de l'aide lol\n<color=#ffd34c>■■■</color> Hé, les canaris ! Vous devriez défoncer tous ces O.C. avec votre vaisseau comme l'autre fois !\n<color=#ffd34c>■■■■</color> Il va pleuvoir de l'éternium mdr"
