L50_1 = "m_SubTitle_KOREA"
L51_1 = "<color=#ffd34c>■■■■</color> 갑자기 애기 침식체 난입함 ㅋㅋㅋㅋ\n<color=#ffd34c>■ ■■</color>ㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋ\n<color=#ffd34c>■■</color> 애기ㅋㅋ 침식체 ㅋㅋ 미쳤냐고 ㅋㅋ 이거 클립 따야겠다\n<color=#ffd34c>■ ■■</color> 침식체가 말도 하네 ㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋ"
L49_1[L50_1] = L51_1
L50_1 = "m_fSubTitleTalkTime"
L49_1[L50_1] = 0
L50_1 = "m_SubTitle_JPN"
L51_1 = "<color=#ffd34c>■■■■</color> いきなりチビ侵食体乱入ｗｗｗｗ\n<color=#ffd34c>■ ■■</color> 大草原\n<color=#ffd34c>■■</color> チビｗｗ侵食体ｗｗオイｗｗこれ切り抜いておこう\n<color=#ffd34c>■ ■■</color> 侵食体が言葉しゃべっとるｗｗｗｗｗｗｗｗｗｗｗｗｗ"
L49_1[L50_1] = L51_1
L50_1 = "m_SubTitle_ENG"
L51_1 = "<color=#ffd34c>■■■■</color> Look! A baby C.O. just barged in!\n<color=#ffd34c>■ ■■</color>LOLOLOLOLOLOL!\n<color=#ffd34c>■■</color> Baby C.O. HAHAHA! That's so funny! I'm clipping this.\n<color=#ffd34c>■ ■■</color> I didn't know C.O.s could talk! LMAO!"
L49_1[L50_1] = L51_1
L50_1 = "m_SubTitle_TWN"
L51_1 = "<color=#ffd34c>■■■■</color> 小朋友侵蝕體突然亂入，呵呵呵\n<color=#ffd34c>■ ■■</color>呵呵呵呵呵呵呵呵呵呵\n<color=#ffd34c>■■</color> 小朋友，呵呵，侵蝕體，呵呵，瘋啦？呵呵。我要上傳限動\n<color=#ffd34c>■ ■■</color> 侵蝕體也會說話喔，呵呵呵呵呵"
L49_1[L50_1] = L51_1
L50_1 = "m_SubTitle_THA"
L51_1 = "<color=#ffd34c>■■■■</color> ดูสิ! เด็กทารกวัตถุคอร์รัปต์เพิ่งบุกเข้ามา!\n<color=#ffd34c>■ ■■</color>555!\n<color=#ffd34c>■■</color> เด็กวัตถุคอร์รัปต์ ฮ่าฮ่าฮ่า! ตลกมาก! ฉันกำลังตัดเรื่องนี้อยู่\n<color=#ffd34c>■ ■■</color> ฉันไม่รู้ว่าวัตถุคอร์รัปต์พูดได้! ฮ่าๆ!"
L49_1[L50_1] = L51_1
L50_1 = "m_SubTitle_VTN"
L51_1 = "<color=#ffd34c>■■■■</color> Nhìn này! Một V.T.A.M. bé vừa xông vào!\n<color=#ffd34c>■ ■■</color>LOLOLOLOLOLOL!\n<color=#ffd34c>■■</color> Bé V.T.A.M. HAHAHA! Hài vậy! Tôi đang cắt đoạn này.\n<color=#ffd34c>■ ■■</color> Tôi không biết V.T.A.M. có thể nói chuyện! CƯỜI CHẾT!"
L49_1[L50_1] = L51_1
L50_1 = "m_SubTitle_SCN"
L51_1 = "<color=#ffd34c>■■■■</color>突然出现了侵蚀体幼童，哈哈哈\n<color=#ffd34c>■ ■■</color>哈哈哈哈哈哈哈哈哈哈笑死\n<color=#ffd34c>■■</color>侵蚀体幼童，噗哈哈哈，疯了吧哈哈哈，截图了\n<color=#ffd34c>■ ■■</color>侵蚀体还会说话呢，啊哈哈哈哈哈哈"
L49_1[L50_1] = L51_1
L50_1 = "m_SubTitle_DEU"
L51_1 = "<color=#ffd34c>■■■■</color> Sieht so aus, als wäre gerade ein Baby-C. O aufgetaucht. Hahaha.\n<color=#ffd34c>■ ■■</color> Ahahahaha.\n<color=#ffd34c>■■</color> Ein Baby-C. O! Ahaha! Ich muss das aufnehmen.\n<color=#ffd34c>■ ■■</color> C.°O.s können also auch sprechen?! LOL!"
L49_1[L50_1] = L51_1
L50_1 = "m_SubTitle_FRA"
L51_1 = "<color=#ffd34c>■■■■</color> Ben ça alors, des bébés O.C. ont fait irruption lol\n<color=#ffd34c>■ ■■</color>JPP !!!\n<color=#ffd34c>■■</color>Des bébés O.C. tu m'as tué ! Faut que je screen ça !\n<color=#ffd34c>■ ■■</color> Alors comme ça, les O.C. peuvent parler mdr"
