L3_1 = "m_SubTitle_KOREA"
L4_1 = "<color=#ffd34c>■■■■</color> 근데 밋치 진짜 놀란 표정인데?\n<color=#ffd34c>■■■■</color> 쫌 위험한 거 아님?\n<color=#ffd34c>■■■</color> 바보냐? 연출이겠지ㅋㅋㅋㅋㅋㅋㅋㅋ\n<color=#ffd34c>■■■</color> 아 엄청 웃기네 진짜 ㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋ"
L2_1[L3_1] = L4_1
L3_1 = "m_fSubTitleTalkTime"
L2_1[L3_1] = 0
L3_1 = "m_SubTitle_JPN"
L4_1 = "<color=#ffd34c>■■■■</color> てかミッチー、マジ驚いた顔してね？\n<color=#ffd34c>■■■■</color> ちょっと危なくね？\n<color=#ffd34c>■■■</color> バカか？　演出だろｗｗｗｗｗｗｗｗ\n<color=#ffd34c>■■■</color> うわめっちゃおもろいｗｗｗｗｗｗｗｗｗｗ"
L2_1[L3_1] = L4_1
L3_1 = "m_SubTitle_ENG"
L4_1 = "<color=#ffd34c>■■■■</color> Mitchie looks genuinely surprised.\n<color=#ffd34c>■■■■</color> Isn't she in danger or something?\n<color=#ffd34c>■■■</color> Don't be stupid. This is all for show! LOL!\n<color=#ffd34c>■■■</color> Man, this is too funny. HAHAHAHA!"
L2_1[L3_1] = L4_1
L3_1 = "m_SubTitle_TWN"
L4_1 = "<color=#ffd34c>■■■■</color> 米琪的臉看起來是真的嚇到欸？\n<color=#ffd34c>■■■■</color> 好危險喔！\n<color=#ffd34c>■■■</color> 傻瓜！想也知道是演的，呵呵呵呵\n<color=#ffd34c>■■■</color> 媽呀，我快笑死，哈哈哈哈哈哈"
L2_1[L3_1] = L4_1
L3_1 = "m_SubTitle_THA"
L4_1 = "<color=#ffd34c>■■■■</color> มิทชี่ดูประหลาดใจจริงๆ\n<color=#ffd34c>■■■■</color> เธอตกอยู่ในอันตรายหรืออะไรบางอย่าง\n<color=#ffd34c>■■■</color> อย่าโง่นะ ทั้งหมดนี้มีไว้เพื่อแสดง! ฮ่าๆ!\n<color=#ffd34c>■■■</color> เพื่อน นี่ตลกเกินไปแล้ว ฮ่า ๆ!"
L2_1[L3_1] = L4_1
L3_1 = "m_SubTitle_VTN"
L4_1 = "<color=#ffd34c>■■■■</color> Mitchie trông thực sự ngạc nhiên.\n<color=#ffd34c>■■■■</color>Cô ấy đang gặp nguy hiểm sao?\n<color=#ffd34c>■■■</color> Đừng ngốc thế. Chỉ là diễn thôi mà! LOL!\n<color=#ffd34c>■■■</color> Ôi trời, chuyện này buồn cười quá. HAHAHAHA!"
L2_1[L3_1] = L4_1
L3_1 = "m_SubTitle_SCN"
L4_1 = "<color=#ffd34c>■■■■</color>米琪好像真的吓到了？\n<color=#ffd34c>■■■■</color>是不是有点危险啊？\n<color=#ffd34c>■■■</color>你们是傻了吧？一看就是演的啊，哈哈哈哈哈\n<color=#ffd34c>■■■</color>笑死我了真的，噗哈哈哈哈哈"
L2_1[L3_1] = L4_1
L3_1 = "m_SubTitle_DEU"
L4_1 = "<color=#ffd34c>■■■■</color> Mitchie scheint aber echt überrascht zu sein?!\n<color=#ffd34c>■■■■</color> Ist Mitchie nicht in Gefahr?\n<color=#ffd34c>■■■</color> Seid ihr dumm? Das war bestimmt abgesprochen! LOL!\n<color=#ffd34c>■■■</color> Ich krieg mich nicht mehr ein!"
L2_1[L3_1] = L4_1
L3_1 = "m_SubTitle_FRA"
L4_1 = "<color=#ffd34c>■■■■</color> Mitchie a vraiment l'air surprise !\n<color=#ffd34c>■■■■</color> C'est pas un peu dangereux ?\n<color=#ffd34c>■■■</color> Vous êtes débiles ou quoi ? C'est sûrement une mise en scène ! lol\n<color=#ffd34c>■■■</color> C'est n'imp' mdr !"
