L10_1 = "DIRECTOR_NPC_NULL_NULL"
L9_1.m_CharStrID = L10_1
L10_1 = "조디악 나이츠는 이슈 메이커라고!"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "ゾディアックナイツはトラブルメーカーなんだよ！"
L9_1.m_Talk_JPN = L10_1
L10_1 = "The Zodiac Knights are issue-makers!"
L9_1.m_Talk_ENG = L10_1
L10_1 = "十二宮騎士團可是話題製造者！"
L9_1.m_Talk_TWN = L10_1
L10_1 = "อัศวินนักษัตรเป็นคนสร้างปัญหา!"
L9_1.m_Talk_THA = L10_1
L10_1 = "Các Hiệp Sĩ Hoàng Đạo là người gây ra vấn đề!"
L9_1.m_Talk_VTN = L10_1
L10_1 = "十二宫骑士可是热点制造者！"
L9_1.m_Talk_SCN = L10_1
