L11_1 = "DIRECTOR_NPC_NULL_NULL"
L10_1.m_CharStrID = L11_1
L11_1 = "이기든, 지든 이건 분명히 화제가 될 거야!"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "勝とうが負けようが、絶対話題になるぞ！"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Everyone's going to be talking about them no matter if they win or lose!"
L10_1.m_Talk_ENG = L11_1
L11_1 = "不管他們贏或輸，一定都會引起話題！"
L10_1.m_Talk_TWN = L11_1
L11_1 = "ทุกคนจะพูดถึงพวกเขาไม่ว่าพวกเขาจะชนะหรือแพ้ก็ตาม!"
L10_1.m_Talk_THA = L11_1
L11_1 = "Mọi người sẽ bàn tán về họ dù họ thắng hay thua!"
L10_1.m_Talk_VTN = L11_1
L11_1 = "无论是输还是赢，肯定能成为热点话题！"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Jeder wird über sie reden, egal ob sie nun gewinnen oder verlieren!"
L10_1.m_Talk_DEU = L11_1
L11_1 = "Tout le monde va en parler, peu importe s'ils gagnent ou perdent !"
L10_1.m_Talk_FRA = L11_1
