L16_1.m_CharScale = L17_1
L16_1.m_CharScaleTime = 0.01
L16_1.m_bCharPinup = true
L17_1 = "저는 아직 어리고, 몸도 약하고…… 무구도 잘 못 다뤄서 정식 기사도 아니지만……."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "私はまだ小さいし、身体も弱いし……武具もちゃんと扱えないから正式の騎士でもないんですけど……"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Though I may be little, weak, and not an official knight because I can't handle an Armament properly..."
L16_1.m_Talk_ENG = L17_1
L17_1 = "雖然我年紀還小，又體弱多病……也不太會使用武具，又不是正式的騎士……"
L16_1.m_Talk_TWN = L17_1
L17_1 = "แม้ว่าฉันจะตัวเล็ก อ่อนแอ และไม่ใช่อัศวินอย่างเป็นทางการ เพราะว่าฉันไม่สามารถจัดการอาวุธยุทโธปกรณ์ได้อย่างเหมาะสม..."
L16_1.m_Talk_THA = L17_1
L17_1 = "Dù tôi có thể nhỏ bé, yếu đuối và không phải là một hiệp sĩ chính thức vì tôi không thể sử dụng Vũ khí đúng cách..."
L16_1.m_Talk_VTN = L17_1
L17_1 = "我现在还小，身体也很弱……而且还不是很会操纵武具，所以不是正式骑士……"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Ich bin vielleicht noch recht klein und schwach ... Und ich bin auch noch kein offizieller Ritter, weil ich mit meiner Bewaffnung nicht richtig umgehen kann ..."
L16_1.m_Talk_DEU = L17_1
L17_1 = "C'est vrai que je suis petite, faible et pas un chevalier officiel parce que je ne sais pas utiliser correctement les armes..."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "CHARADE2_ACT2_STAGE2_START@167#Talk"
L17_1.m_CutScenKey_Talk = L18_1
