L17_1.m_CharStrID = L18_1
L17_1.m_Pos = "C"
L18_1 = {}
L19_1 = 0
L20_1 = -120
L18_1[1] = L19_1
L18_1[2] = L20_1
L17_1.m_CharOffSet = L18_1
L17_1.m_TrackingTime = 0.01
L18_1 = {}
L19_1 = 1.2
L20_1 = 1.2
L18_1[1] = L19_1
L18_1[2] = L20_1
L17_1.m_CharScale = L18_1
L17_1.m_CharScaleTime = 0.01
L17_1.m_bCharPinup = true
L18_1 = "그래도 저…… 매일 같이 옆에서 지켜봤는 걸요. 그러니까 누구보다도 잘 알고 있어요."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "でも私……毎日そばで見てたんです。だから、誰よりもよく知っています。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "But still... I've watched them every day from the sidelines. So I know them better than anyone."
L17_1.m_Talk_ENG = L18_1
L18_1 = "可是我……我可是每天都在旁邊觀察，所以我比誰都清楚！"
L17_1.m_Talk_TWN = L18_1
L18_1 = "แต่ถึงกระนั้น... ฉันก็เฝ้าดูพวกเขาทุกวันจากข้างสนาม ฉันจึงรู้จักพวกเขาดีกว่าใครๆ"
L17_1.m_Talk_THA = L18_1
L18_1 = "Nhưng... tôi vẫn theo dõi họ hàng ngày từ bên lề. Nên, tôi biết họ rõ hơn bất cứ ai."
L17_1.m_Talk_VTN = L18_1
L18_1 = "但我……每天都在旁边看着他们，所以我比任何一个人都清楚。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Aber trotzdem ... habe ich sie jeden Tag vom Spielfeldrand aus beobachtet. Ich kenne sie also besser als jeder andere."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Mais quand même... je les ai bien observés tous les jours depuis la ligne de touche. Je les connais donc mieux que quiconque."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
