L19_1 = "그, 그러니까 말할 수 있어요!"
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "だ、だから言えます！"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Th-that's why I can say this!"
L18_1.m_Talk_ENG = L19_1
L19_1 = "所以，我有資格說！"
L18_1.m_Talk_TWN = L19_1
L19_1 = "ท-นั่นคือเหตุผลที่ฉันสามารถพูดแบบนี้ได้!"
L18_1.m_Talk_THA = L19_1
L19_1 = "Đ-đó là lý do tại sao tôi có thể nói điều này!"
L18_1.m_Talk_VTN = L19_1
L19_1 = "所、所以我才能这么说！"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Deshalb kann ich das sagen kann!"
L18_1.m_Talk_DEU = L19_1
L19_1 = "C'est pourquoi je peux me permettre de dire ceci !"
L18_1.m_Talk_FRA = L19_1
