L21_1.m_Crash = 20
L22_1 = "객석에 있어야 할 에리어스가 왜 밋치미치 방송에?"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "客席にいるはずのアリウスが、なんでミッチーミッチーの番組に？"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Isn't Arius supposed to be with the audience? What's she doing on Mitchie-Mitchie's stream?"
L21_1.m_Talk_ENG = L22_1
L22_1 = "埃里奧斯不是應該坐在觀眾席上嗎？怎麼會出現在米琪的直播裡？"
L21_1.m_Talk_TWN = L22_1
L22_1 = "อาเรียส ควรจะอยู่กับผู้ชมไม่ใช่หรือ? เธอกำลังทำอะไรในสตรีมของมิทชี-มิทชี?"
L21_1.m_Talk_THA = L22_1
L22_1 = "Không phải Arius đang ở chỗ khán giả sao? Em ấy đang làm gì trên kênh của Mitchie-Mitchie?"
L21_1.m_Talk_VTN = L22_1
L22_1 = "本来应该在观众席的埃里奥斯怎么在米琪米琪的直播上出现？"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Sollte Arius nicht im Publikum sitzen? Was macht sie denn in Mitchie-Mitchies Livestream?"
L21_1.m_Talk_DEU = L22_1
L22_1 = "Arius n'est-elle pas censée être avec le public ? Que fait-elle sur le stream de Mitchie-Mitchie ?"
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
