L22_1[L23_1] = L24_1
L23_1 = "으아아, 큰일 났다! 어떡하냐, 한솔아? 이제 우린 부단장한테 죽었어!"
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "うわあ、大変だ！　どうしよう、ヤガミくん！　私たち、副団長に殺されちゃうよ！"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Oh, dear! What do we do, Hansol? Deputy's going to kill us!"
L22_1.m_Talk_ENG = L23_1
L23_1 = "啊啊啊，完蛋了！楊瀚，你說怎麼辦？副團長一定不會放過我們的！"
L22_1.m_Talk_TWN = L23_1
L23_1 = "โอ้ที่รัก! เราจะทำอย่างไรฮันชล? ท่านรองจะฆ่าเรา!"
L22_1.m_Talk_THA = L23_1
L23_1 = "Ôi, trời! Chúng ta phải làm gì đây Hansol? Phó Đội Trưởng sẽ giết chúng ta mất!"
L22_1.m_Talk_VTN = L23_1
L23_1 = "呃啊啊，出大事了！怎么办，杨瀚？这下副团长肯定要杀了我们的！"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Ah, wir sind geliefert! Was sollen wir bloß tun, Hansol? Der stellvertretende Captain wird uns den Hals umdrehen!"
L22_1.m_Talk_DEU = L23_1
L23_1 = "Oh non ! Qu'est-ce qu'on fait Hansol ? La capitaine adjointe va nous tuer !"
L22_1.m_Talk_FRA = L23_1
