L28_1 = "단장님, 부단장님, 리브 언니, 한솔 경…… 그리고 다른 평기사 분들까지."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "団長、副団長、リブさん、ヤガミ卿……それに他の平騎士のみなさんも。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Captain, Deputy, Liv, Sir Hansol... and the rest of the other knight bachelors."
L27_1.m_Talk_ENG = L28_1
L28_1 = "團長，副團長，莉芙姊姊，楊瀚卿……還有其他的平民騎士，"
L27_1.m_Talk_TWN = L28_1
L28_1 = "กัปตัน รอง ลิฟ เซอร์ฮันชล... และอัศวินคนอื่นๆ"
L27_1.m_Talk_THA = L28_1
L28_1 = "Đội trưởng, Đội phó, Liv, Hansol... và những hiệp sĩ khác."
L27_1.m_Talk_VTN = L28_1
L28_1 = "团长、副团长、莉芙姐姐、杨瀚爵士……还有其他普通骑士。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Captain, stellvertretender Captain, Liv, Knappe Hansol ... und der Rest der anderen Ritter."
L27_1.m_Talk_DEU = L28_1
L28_1 = "La capitaine, la capitaine adjointe, dame Liv et sieur Hansol... ainsi que les autres chevaliers émérites."
L27_1.m_Talk_FRA = L28_1
