L28_1.m_bCharPinup = true
L29_1 = "조디악 나이츠는 한 사람도 빠짐없이 어려운 사람을 돕기 위해 노력하고 있다구요!"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "ゾディアックナイツはみんな、困ってる人を助けるために頑張ってるんです！"
L28_1.m_Talk_JPN = L29_1
L29_1 = "The Zodiac Knights are doing their best to help every single person in need!"
L28_1.m_Talk_ENG = L29_1
L29_1 = "十二宮騎士團每一個人都在為幫助有困難的人而努力著！"
L28_1.m_Talk_TWN = L29_1
L29_1 = "อัศวินนักษัตรพยายามอย่างเต็มที่เพื่อช่วยเหลือทุกคนที่ต้องการความช่วยเหลือ!"
L28_1.m_Talk_THA = L29_1
L29_1 = "Các Hiệp Sĩ Hoàng Đạo đang cố gắng hết sức để giúp đỡ mọi người gặp khó khăn!"
L28_1.m_Talk_VTN = L29_1
L29_1 = "十二宫骑士的每一个人都在为帮助有困难的人而努力！"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Die Sternenritter geben ihr Bestes, um jedem einzelnen Menschen in Not zu helfen!"
L28_1.m_Talk_DEU = L29_1
L29_1 = "Les Chevaliers du Zodiaque font de leur mieux pour aider chaque personne dans le besoin !"
L28_1.m_Talk_FRA = L29_1
