L30_1.m_Crash = 30
L31_1 = "리브 경! 이게 대체 어떻게 된 일입니까!"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "アレン卿！　これはいったいどういうことですか！"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Dame Liv! What's going on here?!"
L30_1.m_Talk_ENG = L31_1
L31_1 = "莉芙卿！這到底是怎麼回事！"
L30_1.m_Talk_TWN = L31_1
L31_1 = "อัศวินลิฟ! เกิดอะไรขึ้นที่นี่?!"
L30_1.m_Talk_THA = L31_1
L31_1 = "Liv! Có chuyện gì thế này?"
L30_1.m_Talk_VTN = L31_1
L31_1 = "莉芙爵士！这到底是怎么回事！"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Dame Liv! Was ist denn hier los?!"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Dame Liv ! Que se passe-t-il ici ?!"
L30_1.m_Talk_FRA = L31_1
