L31_1.m_CharStrID = L32_1
L32_1 = "R_M_I"
L31_1.m_Pos = L32_1
L32_1 = "몰라! 나도 모른다구!"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "わかんない！　私にもわかんないよ！"
L31_1.m_Talk_JPN = L32_1
L32_1 = "I dunno! I really don't!"
L31_1.m_Talk_ENG = L32_1
L32_1 = "我怎麼知道！不要問我啦！"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ฉันไม่รู้! ฉันทำไม่ได้จริงๆ!"
L31_1.m_Talk_THA = L32_1
L32_1 = "Tôi không biết! Tôi thực sự không biết!"
L31_1.m_Talk_VTN = L32_1
L32_1 = "不知道！我也不知道！"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Ich weiß es nicht! Ich habe nicht den blassesten Schimmer, was hier vor sich geht!"
L31_1.m_Talk_DEU = L32_1
L32_1 = "Je ne sais pas ! Vraiment !"
L31_1.m_Talk_FRA = L32_1
