L33_1 = "딸기 우유 사주면 객석에 얌전히 있기로 약속했단 말이야!"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "イチゴ牛乳買ってあげたら、客席で大人しくしてるって約束したのに！"
L32_1.m_Talk_JPN = L33_1
L33_1 = "She promised to behave and stay in her seat if I bought her some strawberry milk!"
L32_1.m_Talk_ENG = L33_1
L33_1 = "她明明就答應我，只要我買草莓牛奶給她，她就會乖乖坐在觀眾席上！"
L32_1.m_Talk_TWN = L33_1
L33_1 = "เธอสัญญาว่าจะประพฤติตัวและอยู่ในที่นั่งของเธอถ้าฉันซื้อนมสตรอเบอร์รี่ให้เธอ!"
L32_1.m_Talk_THA = L33_1
L33_1 = "Cô bé hứa sẽ cư xử đúng mực và ngồi yên tại chỗ nếu tôi mua sữa dâu mà!"
L32_1.m_Talk_VTN = L33_1
L33_1 = "明明和她约好了，只要给她买草莓牛奶就会乖乖地待在观众席啊！"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Sie hatte mir versprochen, sich zu benehmen und auf ihrem Platz zu bleiben, wenn ich ihr im Gegenzug eine Erdbeermilch spendiere!"
L32_1.m_Talk_DEU = L33_1
L33_1 = "Elle avait promis de bien se comporter et de rester sur son siège si je lui achetais du lait à la fraise !"
L32_1.m_Talk_FRA = L33_1
