L37_1.m_bCharPinup = true
L38_1 = "원로 할아버지들의 반대를 무릅쓰고, 클리포트 게임에서 모두의 호출에 응한 것도……."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "元老のお爺さんたちの反対も無視して、クリフォトゲームでみんなの呼び出しに応じたのも……"
L37_1.m_Talk_JPN = L38_1
L38_1 = "Responding to everyone's call in the Qliphoth Game in spite of the Elders' opposition..."
L37_1.m_Talk_ENG = L38_1
L38_1 = "不顧元老爺爺們的反對加入逆卡巴拉遊戲……"
L37_1.m_Talk_TWN = L38_1
L38_1 = "ตอบรับเสียงเรียกร้องของทุกคนในเกมคลิฟอธ แม้ว่าคนแก่จะต่อต้านก็ตาม..."
L37_1.m_Talk_THA = L38_1
L38_1 = "Đáp lại lời kêu gọi của mọi người trong Trò chơi Qliphoth mặc kệ sự phản đối của các Trưởng lão..."
L37_1.m_Talk_VTN = L38_1
L38_1 = "不顾元老爷爷们的反对，在神圣战役中回应了所有人的呼叫……"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Auf den Ruf aller im Klippot-Handstreich zu reagieren, trotz des Widerstands der Ältesten ..."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Malgré l'opposition des anciens, nous avons répondu à l'appel de tout le monde lors du Jeu de Qliphoth..."
L37_1.m_Talk_FRA = L38_1
