L39_1 = "에스테로사 단장님이 모든 책임을 지고, 단장직에서 물러나게 된 것도……."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "エステロサ団長がすべての責任を負って、団長職を降りることになったのも……"
L38_1.m_Talk_JPN = L39_1
L39_1 = "And Captain Esterosa taking full responsibility and resigning from her captain position..."
L38_1.m_Talk_ENG = L39_1
L39_1 = "還有艾斯特洛索團長負起所有責任下台一鞠躬……"
L38_1.m_Talk_TWN = L39_1
L39_1 = "และกัปตันเอสเทอโรซ่าก็รับหน้าที่รับผิดชอบเต็มที่และลาออกจากตำแหน่งกัปตัน..."
L38_1.m_Talk_THA = L39_1
L39_1 = "Và Đội trưởng Esterosa nhận toàn bộ trách nhiệm và từ chức đội trưởng..."
L38_1.m_Talk_VTN = L39_1
L39_1 = "艾索团长为了承担全部责任，还辞去了团长职务……"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Und die Tatsache, dass Captain Esterosa die volle Verantwortung übernommen hat und von ihrem Posten als Captain zurückgetreten ist ..."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Et la capitaine Esterosa en a assumé l'entière responsabilité et a démissionné de son poste..."
L38_1.m_Talk_FRA = L39_1
