L40_1 = "모두 민중을…… 모두 여러분의 안녕을 지키기 위해서라고 들었어요!"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "すべて民衆を……みんなの平穏を守るためだって聞きました！"
L39_1.m_Talk_JPN = L40_1
L40_1 = "It was all to keep the people... It was all to keep you safe!"
L39_1.m_Talk_ENG = L40_1
L40_1 = "我聽說……這些全都是為了守護各位！"
L39_1.m_Talk_TWN = L40_1
L40_1 = "ทั้งหมดก็เพื่อปกป้องผู้คน... ทั้งหมดก็เพื่อปกป้องคุณให้ปลอดภัย!"
L39_1.m_Talk_THA = L40_1
L40_1 = "Tất cả là để bảo vệ mọi người... để bảo vệ mọi người được an toàn!"
L39_1.m_Talk_VTN = L40_1
L40_1 = "都是为了民众……为了大家的安宁才那么做的！"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Das alles ist nur zum Wohl des Volkes geschehen! Es ging nur darum, die Menschen zu schützen!"
L39_1.m_Talk_DEU = L40_1
L40_1 = "Tout ça, c'était pour protéger le peuple... Pour assurer votre sécurité à tous !"
L39_1.m_Talk_FRA = L40_1
