L48_1 = "왜 몰라주시는 거예요?"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "どうしてわかってくれないんですか？"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Why can't you see that?"
L47_1.m_Talk_ENG = L48_1
L48_1 = "為什麼大家都不明白呢？"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ทำไมคุณไม่เห็นสิ่งนั้น?"
L47_1.m_Talk_THA = L48_1
L48_1 = "Tại sao mọi người không thấy được điều đó chứ?"
L47_1.m_Talk_VTN = L48_1
L48_1 = "为什么你们都不懂？"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Warum kannst du das nicht sehen?"
L47_1.m_Talk_DEU = L48_1
L48_1 = "Pourquoi ne le comprenez-vous pas ?"
