L48_1.m_CharScale = L49_1
L48_1.m_CharScaleTime = 0.01
L48_1.m_bCharPinup = true
L49_1 = "어째서 다들 알지도 못하면서…… 어떤 사정이 있었는지도 모르면서……."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "どうしてみんな知らないくせに……どんな事情があったかも知らないくせに……"
L48_1.m_Talk_JPN = L49_1
L49_1 = "How can you talk badly of them... when you don't know the full scope...?"
L48_1.m_Talk_ENG = L49_1
L49_1 = "明明什麼不知道……明明不知道內情……"
L48_1.m_Talk_TWN = L49_1
L49_1 = "พูดจาไม่ดีใส่กันได้ยังไง...ในเมื่อไม่รู้เต็มขอบเขต...?"
L48_1.m_Talk_THA = L49_1
L49_1 = "Sao có thể nói xấu họ... khi chẳng ai biết toàn bộ câu chuyện...?"
L48_1.m_Talk_VTN = L49_1
L49_1 = "明明你们什么都不知道……明明不知道发生了什么事……"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Wie kannst du nur schlecht über sie reden ... wenn du nicht einmal die ganze Geschichte kennst ...?"
L48_1.m_Talk_DEU = L49_1
L49_1 = "Comment pouvez-vous d'eux en mal... alors que vous ne connaissez pas toute l'histoire ?"
L48_1.m_Talk_FRA = L49_1
