L49_1.m_CharScaleTime = 0.01
L49_1.m_bCharPinup = true
L50_1 = "왜 다들 그렇게 함부로 나쁜 말을 하는 건가요?"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "なんでみんなそんなに悪く言うんですか？"
L49_1.m_Talk_JPN = L50_1
L50_1 = "When you don't even know what happened...?"
L49_1.m_Talk_ENG = L50_1
L50_1 = "為什麼大家可以輕易說出那麼刻薄的話呢？"
L49_1.m_Talk_TWN = L50_1
L50_1 = "เมื่อไม่รู้ว่าเกิดอะไรขึ้น...?"
L49_1.m_Talk_THA = L50_1
L50_1 = "Khi mọi người còn không biết chuyện gì đã xảy ra...?"
L49_1.m_Talk_VTN = L50_1
L50_1 = "你们为什么要口出恶言？"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Wenn du überhaupt nicht weißt, was genau passiert ist ...?"
L49_1.m_Talk_DEU = L50_1
L50_1 = "Que vous ignorez tout de ce qui s'est passé...?"
L49_1.m_Talk_FRA = L50_1
