L50_1.m_bCharPinup = true
L50_1.m_Crash = 30
L51_1 = "전 어려서 모르는 게 많지만…… 그런 건, 역시 잘 못됐다고 생각해요!"
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "私はまだ子どもで、知らないことがたくさんあるけど……そんなのはやっぱり間違ってると思うんです！"
L50_1.m_Talk_JPN = L51_1
L51_1 = "I'm still young and learning... But what I do know is that this is wrong!"
L50_1.m_Talk_ENG = L51_1
L51_1 = "我年紀小懂的不多……但我也知道這樣是不對的！"
L50_1.m_Talk_TWN = L51_1
L51_1 = "ฉันยังใหม่และกำลังเรียนรู้... แต่สิ่งที่ฉันรู้คือว่านี่มันผิด!"
L50_1.m_Talk_THA = L51_1
L51_1 = "Tôi vẫn còn trẻ con và đang học hỏi... Nhưng tôi biết việc này là sai!"
L50_1.m_Talk_VTN = L51_1
L51_1 = "我还小，还有很多东西不明白……但我觉得，你们的行为是不对的！"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Ich bin jung und habe noch viel zu lernen ... aber ich weiß, dass so ein Verhalten falsch ist!"
L50_1.m_Talk_DEU = L51_1
L51_1 = "Je suis encore jeune et j'apprends... mais ce que je sais, c'est que ce que vous faites est mal !"
L50_1.m_Talk_FRA = L51_1
