L2_1.m_Crash = 20
L3_1 = "에리어스 경, 목소리가…… 떨리고 있어."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "エスクェーデ卿、声が……震えてる。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "Dame Arius, her voice is... trembling."
L2_1.m_Talk_ENG = L3_1
L3_1 = "埃里奧斯卿的聲音……在顫抖。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "นายท่านอาเรียสเสียงของเธอ... ตัวสั่น"
L2_1.m_Talk_THA = L3_1
L3_1 = "Arius, giọng cô bé đang... run rẩy."
L2_1.m_Talk_VTN = L3_1
L3_1 = "埃里奥斯爵士的声音……在颤抖。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Dame Arius, ihre Stimme ... zittert."
L2_1.m_Talk_DEU = L3_1
L3_1 = "Dame Arius, sa voix est... tremblante."
L2_1.m_Talk_FRA = L3_1
