L4_1 = "CHARADE2_ACT2_STAGE2_START@203#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 203
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 5700207
L3_1.m_CutScenStrID = "CHARADE2_ACT2_STAGE2_START"
L3_1.m_bWaitClick = true
