L4_1 = "KNIGHT_NPC_ZODIAC_A"
L3_1.m_CharStrID = L4_1
L3_1.m_Pos = "L"
L4_1 = "몸이 약해서 한 번도 사람들 앞에 나선 적 없으시니까."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "身体が弱くて、一度も人前にお出になったことがないからな。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "She's never spoken up in front of people due to her frailness."
L3_1.m_Talk_ENG = L4_1
L4_1 = "因為她體弱多病，所以從來沒有站在眾人面前過。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "เธอไม่เคยพูดต่อหน้าผู้คนเนื่องจากความอ่อนแอของเธอ"
L3_1.m_Talk_THA = L4_1
L4_1 = "Cô bé chưa bao giờ lên tiếng trước mặt mọi người vì tính cách yếu đuối."
L3_1.m_Talk_VTN = L4_1
L4_1 = "因为身体孱弱的原因，所以从没在公众面前出现过。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Sie hat aufgrund ihres schwachen Körpers noch nie vor Menschen gesprochen."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Elle n'a jamais pris la parole devant les gens à cause de sa condition fragile."
L3_1.m_Talk_FRA = L4_1
