L4_1.m_CharStrID = L5_1
L4_1.m_Pos = "L"
L4_1.m_Crash = 20
L5_1 = "그럼에도 용기를 내고 계셔."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "それでも勇気をふり絞っておられる。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "But still, she is fighting on our behalf."
L4_1.m_Talk_ENG = L5_1
L5_1 = "但她還是鼓起勇氣站出來！"
L4_1.m_Talk_TWN = L5_1
L5_1 = "แต่ถึงกระนั้นเธอก็ต่อสู้เพื่อเรา"
L4_1.m_Talk_THA = L5_1
L5_1 = "Nhưng cô bé vẫn đang chiến đấu cho chúng ta."
L4_1.m_Talk_VTN = L5_1
L5_1 = "但还是鼓起了勇气为我们声援。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Trotzdem hat sie ihren ganzen Mut zusammengenommen und sich für uns eingesetzt."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Et pourtant, elle se bat en notre nom."
L4_1.m_Talk_FRA = L5_1
