L9_1.m_CharScale = L10_1
L9_1.m_CharScaleTime = 0.01
L10_1 = "그러니까 조디악 나이츠 여러분! 피오네 부단장님! 리브 언니! 한솔 경!"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "だから、ゾディアックナイツのみなさん！　フィオネ副団長！　リブさん！　ヤガミ卿！"
L9_1.m_Talk_JPN = L10_1
L10_1 = "So, members of the Zodiac Knights! Deputy Fione! Liv! And Sir Hansol!"
L9_1.m_Talk_ENG = L10_1
L10_1 = "所以十二宮騎士團的大家！菲奧尼副團長！莉芙姊姊！楊瀚卿！"
L9_1.m_Talk_TWN = L10_1
L10_1 = "เอาล่ะ สมาชิกของอัศวินจักรราศี! รองฟิโอเน่! ลิฟ! และเซอร์ฮัน!"
L9_1.m_Talk_THA = L10_1
L10_1 = "Nên các thành viên của Hiệp Sĩ Hoàng Đạo! Phó Đội Trưởng Fione! Liv! Và Hansol!"
L9_1.m_Talk_VTN = L10_1
L10_1 = "所以十二宫骑士的各位！菲奥尼副团长！莉芙姐姐！杨瀚爵士！"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Also, Mitglieder der Sternenritter! Stellvertretender Captain Fione! Liv! Und Knappe Hansol!"
L9_1.m_Talk_DEU = L10_1
L10_1 = "C'est pourquoi les Chevaliers du Zodiaque, la capitaine adjointe Fione, dame Liv et sieur Hansol..."
L9_1.m_Talk_FRA = L10_1
