L10_1[L11_1] = L12_1
L10_1.m_Crash = 30
L11_1 = "저희가 관리국이 주최한 리그에서 우승하는 거예요!"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "私たちが管理局が主催したリーグで優勝するんです！"
L10_1.m_Talk_JPN = L11_1
L11_1 = "We must win this league hosted by the Administration!"
L10_1.m_Talk_ENG = L11_1
L11_1 = "我們要在管理局主辦的聯賽中贏得勝利！"
L10_1.m_Talk_TWN = L11_1
L11_1 = "เราต้องชนะลีกนี้ซึ่งจัดโดยฝ่ายบริหาร!"
L10_1.m_Talk_THA = L11_1
L11_1 = "Chúng ta phải giành chiến thắng giải đấu này của Cục Quản Lý!"
L10_1.m_Talk_VTN = L11_1
L11_1 = "我们必须在联赛中获胜！"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Wir müssen diese von der Administration veranstaltete Liga gewinnen!"
L10_1.m_Talk_DEU = L11_1
L11_1 = "Nous devons gagner cette Compétition organisée par l'Administration !"
L10_1.m_Talk_FRA = L11_1
