L12_1[2] = L14_1
L11_1.m_CharScale = L12_1
L11_1.m_CharScaleTime = 0.01
L11_1.m_Crash = 20
L12_1 = "이 자리에서 조디악 나이츠의 기사도를, 우리의 맹세가 틀리지 않았다는 걸 증명해요!"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "この場でゾディアックナイツの騎士道を、私たちの誓いは間違ってないってことを証明するんです！"
L11_1.m_Talk_JPN = L12_1
L12_1 = "We must prove that our sworn oath, the Zodiac Knight's chivalry, is not wrong!"
L11_1.m_Talk_ENG = L12_1
L12_1 = "我們必須在這裡證明，十二宮騎士團的騎士精神，和我們的誓言是對的！"
L11_1.m_Talk_TWN = L12_1
L12_1 = "เราต้องพิสูจน์ว่าคำสาบานของเรา อัศวินแห่งนักษัตรนั้นไม่ผิด!"
L11_1.m_Talk_THA = L12_1
L12_1 = "Chúng ta phải chứng minh rằng lời thề tinh thần hiệp sĩ của Hiệp Sĩ Hoàng Đạo của chúng ta, là không sai!"
L11_1.m_Talk_VTN = L12_1
L12_1 = "在此证明我们十二宫骑士的骑士信条和誓约没有错误！"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Wir müssen beweisen, dass unser geschworener Eid und die Ritterlichkeit der Sternenritter nicht falsch sind!"
L11_1.m_Talk_DEU = L12_1
L12_1 = "Nous devons prouver que notre serment et notre honneur en tant que Chevaliers du Zodiaque ne sont pas que du vent !"
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
