L12_1.m_CharScale = L13_1
L12_1.m_CharScaleTime = 0.01
L12_1.m_Crash = 30
L13_1 = "그럼, 분명 에스테로사 단장님도 반드시 돌아오실 거예요!"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "そうすればきっと、エステロサ団長も戻ってきます！"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Then, I'm certain that Captain Esterosa will return!"
L12_1.m_Talk_ENG = L13_1
L13_1 = "那我想，艾斯特洛索團長一定也會回來的！"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ถ้าอย่างนั้น ฉันมั่นใจว่ากัปตันเอสเทอโรซ่าจะกลับมา!"
L12_1.m_Talk_THA = L13_1
L13_1 = "Vậy thì em chắc chắn rằng Đội trưởng Esterosa sẽ trở lại!"
L12_1.m_Talk_VTN = L13_1
L13_1 = "那么，艾索团长也肯定会回来的！"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Ich bin sicher, dass Captain Esterosa dann zurückkehren wird!"
L12_1.m_Talk_DEU = L13_1
L13_1 = "Et alors, je suis certaine que la capitaine Esterosa reviendra !"
L12_1.m_Talk_FRA = L13_1
