L13_1[L14_1] = L15_1
L14_1 = "제, 제가 여기서 열심히 응원할게요!"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "わ、私がここで一生懸命応援します！"
L13_1.m_Talk_JPN = L14_1
L14_1 = "I-I will be cheering you on from here!"
L13_1.m_Talk_ENG = L14_1
L14_1 = "我，我會在這裡認真替你們加油的！"
L13_1.m_Talk_TWN = L14_1
L14_1 = "ฉะ-ฉันจะคอยเชียร์คุณต่อจากนี้!"
L13_1.m_Talk_THA = L14_1
L14_1 = "Em sẽ cổ vũ mọi người từ đây!"
L13_1.m_Talk_VTN = L14_1
L14_1 = "我、我会在这里努力为你们加油！"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Ich werde euch alle von hier aus anfeuern!"
L13_1.m_Talk_DEU = L14_1
L14_1 = "Je-Je vous encouragerai d'ici !"
L13_1.m_Talk_FRA = L14_1
