L15_1 = "m_CutScenKey_SubTitle"
L16_1 = "CHARADE2_ACT2_STAGE2_START@214#SubTitle"
L14_1[L15_1] = L16_1
L15_1 = 214
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 5700207
L14_1.m_CutScenStrID = "CHARADE2_ACT2_STAGE2_START"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L15_1 = "m_fTitleTalkTime"
L14_1[L15_1] = 0
L15_1 = "m_SubTitle_KOREA"
L16_1 = "<color=#ffd34c>■■</color> 잠깐, 넷튜브 영상들 보니까, 조디악 나이츠 엄청 센데?\n<color=#ffd34c>■■</color> 샤레이드에 출몰했던 사채업자랑 싸우는 영상도 있어.\n<color=#ffd34c>■■■■</color> 당연히 조작이겠지! 그런 식으로 몸값 불리는 태스크포스가 얼마나 많은데."
L14_1[L15_1] = L16_1
L15_1 = "m_fSubTitleTalkTime"
L14_1[L15_1] = 0
L15_1 = "m_SubTitle_JPN"
L16_1 = "<color=#ffd34c>■■</color> 待てよ、ネットチューブ映像見てみたら、ゾディアックナイツめっちゃ強いぞ？\n<color=#ffd34c>■■</color> シャレードに現れた闇金業者と戦う映像もある。\n<color=#ffd34c>■■■■</color> 捏造に決まってるだろ！　そんな風にギャラ上げるタスクフォースって山ほどいるんだよ？"
L14_1[L15_1] = L16_1
L15_1 = "m_SubTitle_ENG"
L16_1 = "<color=#ffd34c>■■</color> Wait, I just watched them on NetTube, and the Zodiac Knights are really strong!\n<color=#ffd34c>■■</color> There's even a video of them fighting that loan shark that suddenly appeared in Charade.\n<color=#ffd34c>■■■■</color> Of course it's all fake! Do you know how many TASKFORCEs use that exact method to increase their worth?"
L14_1[L15_1] = L16_1
L15_1 = "m_SubTitle_TWN"
L16_1 = "<color=#ffd34c>■■</color> 等等，我看網路上的影片，十二宮騎士團超強欸？\n<color=#ffd34c>■■</color> 還有他們跟在查雷德出沒的高利貸業者打架的影片。\n<color=#ffd34c>■■■■</color> 這都是事前Set好的吧？很多特遣勢力都會用這招來拉抬身價。"
L14_1[L15_1] = L16_1
L15_1 = "m_SubTitle_THA"
L16_1 = "<color=#ffd34c>■■</color> เดี๋ยวก่อน ฉันเพิ่งดูพวกเขาใน NetTube และอัศวินนักษัตรก็แข็งแกร่งมาก!\n<color=#ffd34c>■■</color> มีแม้แต่วิดีโอที่พวกเขาต่อสู้กันด้วยซ้ำ ไอ้เจ้าหนี้ตัวนั้นที่จู่ๆ ก็ปรากฏตัวในชาเรด\n<color=#ffd34c>■■■■</color> แน่นอนว่าทั้งหมดเป็นของปลอม! คุณรู้หรือไม่ว่ามีทาสก์ฟอร์สกี่คนที่ใช้วิธีการที่แน่นอนนั้นเพื่อเพิ่มมูลค่าของพวกเขา?"
L14_1[L15_1] = L16_1
L15_1 = "m_SubTitle_VTN"
L16_1 = "<color=#ffd34c>■■</color> Đợi đã, tôi vừa xem họ trên NetTube, và các Hiệp Sĩ Hoàng Đạo thực sự rất mạnh!\n<color=#ffd34c>■■</color> Thậm chí còn có một video quay cảnh họ chiến đấu với kẻ cho vay nặng lãi đột nhiên xuất hiện ở Charade.\n<color=#ffd34c>■■■■</color> Tất nhiên là đồ giả rồi! Có biết có bao nhiêu TASKFORCE dùng cách đó để nổi tiếng không?"
L14_1[L15_1] = L16_1
L15_1 = "m_SubTitle_SCN"
L16_1 = "<color=#ffd34c>■■</color>等等，我去看了NetTube的视频，十二宫骑士好像很厉害啊？\n<color=#ffd34c>■■</color>还有和出没在查雷德的高利贷打架的视频呢。\n<color=#ffd34c>■■■■</color>肯定是捏造的！好多特遣势力都是用那种方法提高身价的。"
L14_1[L15_1] = L16_1
L15_1 = "m_SubTitle_DEU"
L16_1 = "<color=#ffd34c>■■</color> Moment mal, ich habe mir gerade bei NetTube ein Video der Sternenritter angesehen und die sind ganz schön stark?!\n<color=#ffd34c>■■</color> Es gibt sogar ein Video, wo sie gegen den Kredithai kämpfen, der in Charade aufgetaucht ist.\n<color=#ffd34c>■■■■</color> Das ist doch alles gestellt! Wisst ihr eigentlich, wie viele TASKFORCEs versuchen auf diese Weise ihren Wert zu erhöhen?!"
L14_1[L15_1] = L16_1
L15_1 = "m_SubTitle_FRA"
L16_1 = "<color=#ffd34c>■■</color> Eh mais, je regarde les vidéos de NetTube et en fait ils sont vachement forts les Chevaliers du Zodiaque !\n<color=#ffd34c>■■</color> Y'a même une vidéo de combat contre une prêteuse à gages apparue à Charade.\n<color=#ffd34c>■■■■</color> Tout ça c'est des montages ! Y'a plein de TASKFORCEs qui font ça pour se la péter !"
L14_1[L15_1] = L16_1
