L20_1.m_CharStrID = L21_1
L20_1.m_Pos = "R"
L20_1.m_Crash = 20
L21_1 = "에리어스 말대로 저희의 실력을 사람들에게 증명할 때라고요!"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "アリウスの言うとおり、我々の実力をみんなに証明する時です！"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Like Arius said, the time has come to prove our skills to the people!"
L20_1.m_Talk_ENG = L21_1
L21_1 = "就像埃里奧斯所說的，現在是向眾人證明我們實力的時候！"
L20_1.m_Talk_TWN = L21_1
L21_1 = "อย่างที่อาเรียสพูด ถึงเวลาพิสูจน์ทักษะของเราต่อผู้คนแล้ว!"
L20_1.m_Talk_THA = L21_1
L21_1 = "Giống như Arius đã nói, đã đến lúc chứng tỏ cho người ta thấy kỹ năng của chúng ta!"
L20_1.m_Talk_VTN = L21_1
L21_1 = "就像埃里奥斯所说，是时候向人们证明我们的实力了！"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Wie Arius sagte, ist es an der Zeit, den Menschen unsere Fähigkeiten zu beweisen!"
L20_1.m_Talk_DEU = L21_1
L21_1 = "Comme Arius l'a dit, le moment est venu de prouver notre valeur !"
L20_1.m_Talk_FRA = L21_1
