L24_1 = 2
L25_1 = 0.15
L23_1[1] = L24_1
L23_1[2] = L25_1
L21_1[L22_1] = L23_1
L22_1 = "그래! 에리어스가 저렇게까지 응원해주는데 우리 실력을 보여줘야 하지 않겠어?"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "そうだよ！　アリウスがあんなに応援してくれてるんだし、私たちの実力を見せつけてやらなきゃ！"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Yeah! After seeing Arius cheer us on like that, we have to show them something, right?"
L21_1.m_Talk_ENG = L22_1
L22_1 = "沒錯！埃里奧斯那麼認真為我們加油，當然要好好表現一下我們的實力囉？"
L21_1.m_Talk_TWN = L22_1
L22_1 = "ใช่! เห็นอาเรียสเชียร์เราแบบนั้นแล้วก็ต้องแสดงอะไรให้พวกเขาเห็นใช่ไหม?"
L21_1.m_Talk_THA = L22_1
L22_1 = "Sự chân thành của cô bé đã lật ngược tình thế trước khi trận đấu bắt đầu."
L21_1.m_Talk_VTN = L22_1
L22_1 = "没错！埃里奥斯真心为我们加油，那我们也该拿出我们的实力了！"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Ja! Da Arius ​​uns so anfeuert, sollten wir unser Können unter Beweis stellen!"
L21_1.m_Talk_DEU = L22_1
L22_1 = "Oui ! Après avoir vu Arius nous encourager comme ça, nous devons leur donner de quoi se mettre sous la dent, non ?"
L21_1.m_Talk_FRA = L22_1
