L25_1 = "CHARADE2_ACT2_STAGE2_START@224#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 224
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 5700207
L24_1.m_CutScenStrID = "CHARADE2_ACT2_STAGE2_START"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_Face = "UNIT_SERIOUS"
L25_1 = "PIONE_ZODIAC_NULL_NULL"
L24_1.m_CharStrID = L25_1
L24_1.m_Pos = "C"
L25_1 = "다들 냉정해지세요. 우리가 리그에 참가한 이유는 그런 사적인 이유가 아닙니다."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "皆さん、冷静になってください。私たちがリーグに参加した理由は、そのような私的な理由ではありません。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "Everyone, keep your cool. We have not participated in the league for something as personal as that."
L24_1.m_Talk_ENG = L25_1
L25_1 = "你們冷靜點，我們參加聯賽的理由，並不是因為私人的原因。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "ทุกคน ใจเย็นไว้นะ เราไม่ได้เข้าร่วมลีกเพื่อเรื่องส่วนตัวขนาดนั้น"
L24_1.m_Talk_THA = L25_1
L25_1 = "Mọi người hãy bình tĩnh nhé. Chúng ta chưa từng tham gia giải đấu vì mục đích cá nhân như vậy."
L24_1.m_Talk_VTN = L25_1
L25_1 = "大家都冷静一下。我们参加联赛，并不是为了那种私人理由。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Behaltet alle einen kühlen Kopf. Wir haben nicht aus so einem persönlichen Grund an der Liga nicht teilgenommen."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Gardez votre sang-froid, vous tous. Nous n'avons pas décidé de participer à la Compétition dans un but personnel."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
