L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L26_1 = "PIONE_ZODIAC_NULL_NULL"
L25_1.m_CharStrID = L26_1
L25_1.m_Pos = "C"
L26_1 = "대중의 평가가 어떻든, 우리는 그저 우리의 책무를 다할 뿐입니다."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "大衆の評価がどうあれ、私たちはただ自分たちの責務を果たすまでです。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "Whatever the public may think of us, we are here to perform our duties."
L25_1.m_Talk_ENG = L26_1
L26_1 = "無論大眾對我們的評價如何，我們都只是善盡職責而已。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "ไม่ว่าสาธารณชนจะคิดอย่างไรกับเรา เราก็พร้อมจะทำหน้าที่ของเรา"
L25_1.m_Talk_THA = L26_1
L26_1 = "Dù công chúng có nghĩ gì về chúng ta thì chúng ta vẫn ở đây để thực hiện nhiệm vụ của mình."
L25_1.m_Talk_VTN = L26_1
L26_1 = "不管大众对我们的评价如何，我们只需尽我们的责任就好。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Was auch immer die Öffentlichkeit über uns denken mag, wir sind hier, um unsere Pflichten zu erfüllen."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Quoi que le public pense de nous, nous sommes ici car notre devoir l'exige."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
