L32_1.m_CharScaleTime = 0.01
L32_1.m_bCharPinup = true
L33_1 = "우리의 책무를 위해서는 리그에서 반드시 우승해야합니다!"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "私たちの責務のためには、必ずリーグで優勝しなければなりません！"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Today is a very lucky day."
L32_1.m_Talk_ENG = L33_1
L33_1 = "我們的職責就是要贏得聯賽！"
L32_1.m_Talk_TWN = L33_1
L33_1 = "วันนี้เป็นวันที่โชคดีมาก"
L32_1.m_Talk_THA = L33_1
L33_1 = "Hôm nay là một ngày rất may mắn."
L32_1.m_Talk_VTN = L33_1
L33_1 = "为了尽责，我们必须在联赛夺得冠军！"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Heute ist ein sehr glücklicher Tag."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Aujourd'hui est notre jour de chance !"
L32_1.m_Talk_FRA = L33_1
