L34_1 = "그러니 오늘은 아주 운이 좋군요."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "ですので、今日はとてもついていますね。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Because it seems we need to claim victory in the league in order to fulfill our duties!"
L33_1.m_Talk_ENG = L34_1
L34_1 = "所以今天非常幸運。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "เพราะดูเหมือนว่าเราจะต้องคว้าชัยชนะในลีกเพื่อทำหน้าที่ของเราให้สำเร็จ!"
L33_1.m_Talk_THA = L34_1
L34_1 = "Bởi vì có vẻ như chúng ta cần phải giành chiến thắng để hoàn thành nhiệm vụ!"
L33_1.m_Talk_VTN = L34_1
L34_1 = "所以今天是运气非常好的一天。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Denn es scheint, dass wir den Sieg in der Liga erringen müssen, um unsere Pflichten zu erfüllen!"
L33_1.m_Talk_DEU = L34_1
L34_1 = "Nous devons remporter la victoire dans la Compétition afin de remplir nos devoirs !"
L33_1.m_Talk_FRA = L34_1
