L34_1.m_Crash = 30
L35_1 = "조디악 나이츠, 전원! 이번 기회에 대중에게 기사도의 긍지를 확실하게 보여주도록!"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "ゾディアックナイツ、総員！　これを機に、大衆に騎士道の何たるかをはっきりと見せてやるんだ！"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Zodiac Knights! Now is the time to demonstrate true chivalric honor for all to see!"
L34_1.m_Talk_ENG = L35_1
L35_1 = "十二宮騎士團全員聽著！我們要藉著這次機會，向大眾展現我們引以為傲的騎士精神！"
L34_1.m_Talk_TWN = L35_1
L35_1 = "อัศวินนักษัตร! ตอนนี้เป็นเวลาที่จะแสดงเกียรติยศแห่งอัศวินที่แท้จริงให้ทุกคนได้เห็น!"
L34_1.m_Talk_THA = L35_1
L35_1 = "Hiệp Sĩ Hoàng Đạo! Bây giờ là lúc để thể hiện danh dự hiệp sĩ thực sự cho tất cả cùng xem!"
L34_1.m_Talk_VTN = L35_1
L35_1 = "十二宫骑士全体成员！借此机会向大众好好展示一下骑士信条的自豪吧！"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Sternenritter! Nutzen wir diese Gelegenheit, um der Öffentlichkeit den Stolz des Rittertums deutlich zu demonstrieren!"
L34_1.m_Talk_DEU = L35_1
L35_1 = "Chevaliers du Zodiaque ! Il est maintenant temps de montrer à tous ce qu'est la noblesse des chevaliers !"
L34_1.m_Talk_FRA = L35_1
