L45_1 = "으아아! 왠지 이러니까 우리가 악당이 된 것 같아요!"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "わああ！　これ、なんだか私たちが悪党みたいですよ！"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Nuaagh! This makes us look like the villains!"
L44_1.m_Talk_ENG = L45_1
L45_1 = "啊咧咧！怎麼搞得我們反而像壞人一樣！"
L44_1.m_Talk_TWN = L45_1
L45_1 = "ว้ากกก! นี่ทำให้เราดูเหมือนผู้ร้าย!"
L44_1.m_Talk_THA = L45_1
L45_1 = "Không! Cái này làm chúng ta trông như mấy kẻ phản diện!"
L44_1.m_Talk_VTN = L45_1
L45_1 = "呃啊啊！这样一来好像显得我们是坏人一样！"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Aaah! Das lässt uns irgendwie wie die Bösen dastehen!"
L44_1.m_Talk_DEU = L45_1
L45_1 = "Aarrgh ! Mais ça nous fait passer pour les méchants !"
L44_1.m_Talk_FRA = L45_1
