L47_1 = "m_fFlashBangTime"
L46_1[L47_1] = 0.5
L47_1 = "FX_CUTSCEN_BEEP"
L46_1.m_StartFXSoundName = L47_1
L47_1 = "STAFF_CANARY_NULL_NULL"
L46_1.m_CharStrID = L47_1
L46_1.m_Pos = "L"
L47_1 = "m_bCharHologramEffect"
L46_1[L47_1] = true
L47_1 = "맞는 말이야. 실제로 부정적이었던 스트리밍 반응도 역전됐어."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "確かに。実際に否定的だったネットの反応も逆転してるわ。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "She's right. The audience watching the stream has all turned against us."
L46_1.m_Talk_ENG = L47_1
L47_1 = "你說的沒錯，現在直播平台上的風向也開始倒向他們。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "เธอพูดถูก ผู้ชมที่ดูสตรีมต่างก็หันมาต่อต้านเรา"
L46_1.m_Talk_THA = L47_1
L47_1 = "Cô ấy nói đúng. Khán giả xem buổi phát sóng đều quay lưng lại với chúng ta."
L46_1.m_Talk_VTN = L47_1
L47_1 = "你说得没错。现在直播的负面舆论都指向我们了。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Sie hat recht. Die Zuschauer des Livestreams haben sich auch gegen uns gewandt."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Elle a raison. Le public qui regarde le stream s'est retourné contre nous."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "CHARADE2_ACT2_STAGE2_START@247#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 247
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 5700207
