L47_1.m_Face = "UNIT_SERIOUS"
L48_1 = "STAFF_CANARY_NULL_NULL"
L47_1.m_CharStrID = L48_1
L47_1.m_Pos = "L"
L47_1.m_Crash = 20
L48_1 = "저 아이의 진심이 경기가 시작되기 전부터 분위기를 바꾼 거야."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "あの子の気持ちが、試合が始まる前から雰囲気を変えたんだわ。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "The girl's sincerity turned the tide before the match even began."
L47_1.m_Talk_ENG = L48_1
L48_1 = "那個孩子誠摯的發言，在比賽開始前就已經改變整個氛圍。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ความจริงใจของหญิงสาวทำให้เกิดกระแสก่อนที่การแข่งขันจะเริ่มต้นขึ้นด้วยซ้ำ"
L47_1.m_Talk_THA = L48_1
L48_1 = "Sự chân thành của cô bé đó đã lật ngược tình thế trước khi trận đấu bắt đầu."
L47_1.m_Talk_VTN = L48_1
L48_1 = "那个孩子用真诚在比赛开始前扭转了氛围。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Die Aufrichtigkeit dieses Mädchens hat das Blatt gewendet, bevor das Spiel überhaupt begonnen hat."
L47_1.m_Talk_DEU = L48_1
L48_1 = "La sincérité de cette enfant a fait changer le cours du match avant même qu'il ne commence."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
