L50_1 = "상대 팀의 기세가 만만치 않네. 조심하도록."
L49_1.m_Talk_KOREA = L50_1
L50_1 = "相手チームの勢いがすごい。気をつけたまえ。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "Our opponent's spirit is not to be taken lightly. Be careful out there."
L49_1.m_Talk_ENG = L50_1
L50_1 = "對方的氣勢不容小覷，大家要小心。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "จิตวิญญาณของคู่ต่อสู้ของเราไม่ควรมองข้าม ระวังข้างนอกด้วย"
L49_1.m_Talk_THA = L50_1
L50_1 = "Tinh thần của đối thủ không thể xem nhẹ được. Hãy cẩn thận nhé."
L49_1.m_Talk_VTN = L50_1
L50_1 = "对手的气势很不一般，大家小心点。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Der Kampfgeist unseres Gegners darf nicht unterschätzt werden. Seid vorsichtig."
L49_1.m_Talk_DEU = L50_1
L50_1 = "L'enthousiasme de notre adversaire ne doit pas être pris à la légère. Soyez prudentes là-bas."
L49_1.m_Talk_FRA = L50_1
